// Improved application with security best practices
const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(xss()); // Sanitize user input against XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Validate and sanitize query parameters
  const allowedParams = ['limit', 'offset', 'sort'];
  const invalidParams = Object.keys(req.query).filter(
    param => !allowedParams.includes(param)
  );

  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: 'Bad Request',
      message: `Invalid query parameters: ${invalidParams.join(', ')}`
    });
  }

  // Sanitize numeric parameters
  if (req.query.limit && (!/^\d+$/.test(req.query.limit) || parseInt(req.query.limit) > 100)) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Limit must be a positive integer not exceeding 100'
    });
  }

  if (req.query.offset && !/^\d+$/.test(req.query.offset)) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Offset must be a non-negative integer'
    });
  }

  next();
};

// Health check endpoint with proper error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to retrieve health status'
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    // Apply pagination if requested
    let filteredUsers = users;

    if (req.query.limit || req.query.offset) {
      const limit = parseInt(req.query.limit) || users.length;
      const offset = parseInt(req.query.offset) || 0;
      filteredUsers = users.slice(offset, offset + limit);
    }

    // Apply sorting if requested
    if (req.query.sort) {
      const sortField = req.query.sort.startsWith('-') 
        ? req.query.sort.substring(1) 
        : req.query.sort;
      const sortOrder = req.query.sort.startsWith('-') ? -1 : 1;

      if (['id', 'name', 'email'].includes(sortField)) {
        filteredUsers.sort((a, b) => {
          if (a[sortField] < b[sortField]) return -1 * sortOrder;
          if (a[sortField] > b[sortField]) return 1 * sortOrder;
          return 0;
        });
      }
    }

    res.json({
      status: 'success',
      count: filteredUsers.length,
      data: filteredUsers
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Default to 500 if status code is not set
  const statusCode = err.status || 500;

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : 'Bad Request',
    message: err.message || 'An unexpected error occurred',
    // Only include stack trace in development
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

