/**
 * Test script to verify credentials in .env.test
 * This script attempts to connect to services using the credentials
 * and reports on their validity.
 */

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  try {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    await client.query('SELECT NOW()');
    await client.end();
    console.log('✅ Database connection successful');
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    return false;
  }
}

async function testAWSConnection() {
  console.log('Testing AWS connection...');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  try {
    // Configure AWS SDK
    AWS.config.update({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1' // Default region
    });

    // Try to list S3 buckets (a low-cost operation)
    const s3 = new AWS.S3();
    const data = await s3.listBuckets().promise();
    console.log(`✅ AWS connection successful. Found ${data.Buckets.length} S3 buckets.`);
    return true;
  } catch (error) {
    console.log(`❌ AWS connection failed: ${error.message}`);
    return false;
  }
}

async function testAnthropicAPI() {
  console.log('Testing Anthropic API connection...');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  try {
    const response = await axios.post(
      'https://api.anthropic.com/v1/messages',
      {
        model: 'claude-3-haiku-20240307',
        max_tokens: 10,
        messages: [{ role: 'user', content: 'Hello' }]
      },
      {
        headers: {
          'x-api-key': process.env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        }
      }
    );

    if (response.status === 200 && response.data.content) {
      console.log('✅ Anthropic API connection successful');
      return true;
    } else {
      console.log(`❌ Anthropic API returned unexpected status: ${response.status}`);
      return false;
    }
  } catch (error) {
    if (error.response) {
      console.log(`❌ Anthropic API returned status ${error.response.status}: ${error.response.data.error?.message || 'Unknown error'}`);
    } else {
      console.log(`❌ Anthropic API connection failed: ${error.message}`);
    }
    return false;
  }
}

async function testStripeAPI() {
  console.log('Testing Stripe API connection...');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found in environment');
    return false;
  }

  try {
    const response = await axios.get(
      'https://api.stripe.com/v1/account',
      {
        headers: {
          'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`
        }
      }
    );

    if (response.status === 200) {
      console.log('✅ Stripe API connection successful');
      return true;
    } else {
      console.log(`❌ Stripe API returned unexpected status: ${response.status}`);
      return false;
    }
  } catch (error) {
    if (error.response) {
      console.log(`❌ Stripe API returned status ${error.response.status}: ${error.response.data.error?.message || 'Unknown error'}`);
    } else {
      console.log(`❌ Stripe API connection failed: ${error.message}`);
    }
    return false;
  }
}

async function main() {
  console.log('=== Credential Validation Test ===\n');

  // Load environment variables from .env.test
  require('dotenv').config({ path: '.env.test' });

  // Install required packages if not present
  const fs = require('fs');
  const path = require('path');

  const packageJsonPath = path.resolve('./package.json');
  let packageJson = {};

  try {
    const packageContent = fs.readFileSync(packageJsonPath, 'utf8');
    packageJson = JSON.parse(packageContent);
  } catch (err) {
    console.log('Warning: Could not read package.json');
  }

  // Test each service
  const results = {};

  results.database = await testDatabaseConnection();
  console.log('');

  results.aws = await testAWSConnection();
  console.log('');

  results.anthropic = await testAnthropicAPI();
  console.log('');

  results.stripe = await testStripeAPI();
  console.log('');

  // Summary
  console.log('=== Test Summary ===');
  const passed = Object.values(results).filter(Boolean).length;
  const total = Object.values(results).length;

  console.log(`Passed: ${passed}/${total}`);

  for (const [service, result] of Object.entries(results)) {
    console.log(`${service.charAt(0).toUpperCase() + service.slice(1)}: ${result ? '✅ PASS' : '❌ FAIL'}`);
  }

  return passed === total;
}

// Run the test if this file is executed directly
if (require.main === module) {
  main().then(success => {
    process.exit(success ? 0 : 1);
  }).catch(err => {
    console.error('Unhandled error in test script:', err);
    process.exit(1);
  });
}

module.exports = { testDatabaseConnection, testAWSConnection, testAnthropicAPI, testStripeAPI };

