/**
 * Simple test script to check if credentials in .env.test have valid format
 * This doesn't actually connect to services but validates the format
 */

const fs = require('fs');
const path = require('path');

function loadEnvFile(filePath) {
  const envVars = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
      line = line.trim();
      if (line && !line.startsWith('#') && line.includes('=')) {
        const [key, value] = line.split('=');
        envVars[key.trim()] = value.trim();
      }
    });
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
  }

  return envVars;
}

function validateDatabaseURL(url) {
  if (!url) return { valid: false, reason: 'Missing DATABASE_URL' };

  // Basic PostgreSQL URL format validation
  const pgPattern = /^postgres(ql)?:\/\/[^:]+:[^@]+@[^:\s]+:\d+\/[^\s]+$/;
  if (!pgPattern.test(url)) {
    return { valid: false, reason: 'Invalid PostgreSQL URL format' };
  }

  // Check for canary values
  if (url.includes('CANARY')) {
    return { valid: false, reason: 'Contains CANARY placeholder - likely stale/test credentials' };
  }

  return { valid: true, reason: 'URL format appears valid' };
}

function validateAWSKey(key) {
  if (!key) return { valid: false, reason: 'Missing AWS_ACCESS_KEY_ID' };

  // AWS Access Key ID format: 20 characters, uppercase letters and digits
  if (!/^[A-Z0-9]{20}$/.test(key)) {
    return { valid: false, reason: 'Invalid AWS Access Key ID format' };
  }

  // Check for canary values
  if (key.includes('CANARY')) {
    return { valid: false, reason: 'Contains CANARY placeholder - likely stale/test credentials' };
  }

  return { valid: true, reason: 'AWS Access Key ID format appears valid' };
}

function validateAWSSecret(secret) {
  if (!secret) return { valid: false, reason: 'Missing AWS_SECRET_ACCESS_KEY' };

  // AWS Secret Access Key format: 40 characters, alphanumeric and special chars
  if (secret.length < 30) { // Minimum reasonable length
    return { valid: false, reason: 'AWS Secret Access Key too short' };
  }

  // Check for canary values
  if (secret.includes('CANARY')) {
    return { valid: false, reason: 'Contains CANARY placeholder - likely stale/test credentials' };
  }

  return { valid: true, reason: 'AWS Secret Access Key length appears reasonable' };
}

function validateAPIKey(key, serviceName) {
  if (!key) return { valid: false, reason: `Missing ${serviceName.toUpperCase()}_API_KEY` };

  // Basic validation - should be reasonably long
  if (key.length < 10) {
    return { valid: false, reason: `${serviceName} API key too short` };
  }

  // Check for canary values
  if (key.includes('CANARY')) {
    return { valid: false, reason: 'Contains CANARY placeholder - likely stale/test credentials' };
  }

  return { valid: true, reason: `${serviceName} API key length appears reasonable` };
}

function validateStripeKey(key) {
  if (!key) return { valid: false, reason: 'Missing STRIPE_SECRET_KEY' };

  // Stripe secret keys typically start with sk_live_ or sk_test_
  if (!/^sk_(live|test)_/.test(key)) {
    return { valid: false, reason: 'Invalid Stripe secret key format (should start with sk_live_ or sk_test_)' };
  }

  // Check for canary values
  if (key.includes('CANARY')) {
    return { valid: false, reason: 'Contains CANARY placeholder - likely stale/test credentials' };
  }

  return { valid: true, reason: 'Stripe secret key format appears valid' };
}

function main() {
