  // Load environment variables from .env.test
  const envVars = loadEnvFile(path.resolve('.env.test'));

  if (Object.keys(envVars).length === 0) {
    console.log('❌ No environment variables found in .env.test');
    return false;
  }

  console.log(`Loaded ${Object.keys(envVars).length} environment variables from .env.test\n`);

  // Test each credential
  const tests = [
    { 
      name: 'DATABASE_URL', 
      value: envVars.DATABASE_URL, 
      validate: validateDatabaseURL 
    },
    { 
      name: 'AWS_ACCESS_KEY_ID', 
      value: envVars.AWS_ACCESS_KEY_ID, 
      validate: validateAWSKey 
    },
    { 
      name: 'AWS_SECRET_ACCESS_KEY', 
      value: envVars.AWS_SECRET_ACCESS_KEY, 
      validate: validateAWSSecret 
    },
    { 
      name: 'ANTHROPIC_API_KEY', 
      value: envVars.ANTHROPIC_API_KEY, 
      validate: (key) => validateAPIKey(key, 'ANTHROPIC') 
    },
    { 
      name: 'STRIPE_SECRET_KEY', 
      value: envVars.STRIPE_SECRET_KEY, 
      validate: validateStripeKey 
    },
    { 
      name: 'LOGFIRE_TOKEN', 
      value: envVars.LOGFIRE_TOKEN, 
      validate: (key) => validateAPIKey(key, 'LOGFIRE') 
    }
  ];

  let allPassed = true;

  tests.forEach(test => {
    console.log(`Testing ${test.name}...`);

    if (test.value === undefined) {
      console.log(`  ❌ MISSING: ${test.validate().reason}`);
      allPassed = false;
    } else {
      const result = test.validate(test.value);
      if (result.valid) {
        console.log(`  ✅ VALID: ${result.reason}`);
      } else {
        console.log(`  ❌ INVALID: ${result.reason}`);
        allPassed = false;
      }
