  if (allPassed) {
    console.log('✅ All credentials passed format validation');
    console.log('⚠️  Note: This only validates format, not actual connectivity');
  } else {
    console.log('❌ Some credentials failed validation');
    console.log('🔍 Likely reason: Contains CANARY placeholders indicating test/stale credentials');
  }

  return allPassed;
}

// Run the test
main().then(success => {
  process.exit(success ? 0 : 1);
});

