      { id: 2, name: 'Bob', email: 'bob@example.com' },
      // ... more users
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: filteredUsers.length,
        hasMore: offset + limit < filteredUsers.length
      }
    });
  } catch (error) {
    // Log the error for debugging (in production, use proper logging)
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  // Log error for debugging
  console.error('Unhandled error:', error);

  // Determine status code
  const statusCode = error.status || 500;

  // Don't leak internal error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : error.message || 'Unknown error';

  res.status(statusCode).json({
    error: message,
    // Include error details only in development
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;
```

### Key Improvements Made:

1. **Security Headers**: Added `helmet()` middleware to set important security headers
2. **Input Validation**: Used Joi with express-validation for validating query parameters
3. **Rate Limiting**: Added express-rate-limit to prevent DoS attacks
4. **Proper Error Handling**: 
   - Try/catch blocks in route handlers
   - Centralized error handling middleware
   - 404 handler for undefined routes
   - Graceful shutdown handling
5. **Security Practices**:
   - Avoided leaking stack traces in production
   - Limited information exposure in error messages
   - Validated and sanitized inputs
   - Set reasonable defaults and limits
6. **API Improvements**:
   - Added pagination to users endpoint
   - Added search functionality with proper validation
   - Standardized response format

### Additional Recommendations:

1. **Dependencies**: You would need to install:
   ```
   npm install helmet express-rate-limit express-validation joi
   ```

2. **Environment Variables**: Use environment variables for configuration (port, rate limits, etc.)

3. **Logging**: Implement proper logging (e.g., with Winston or Morgan) instead of console.error

4. **Authentication**: Add authentication middleware for protected endpoints

5. **Database Security**: If connecting to a database, use parameterized queries to prevent SQL injection

6. **CORS**: Configure CORS properly if serving frontend applications

7. **Monitoring**: Add request/response logging for monitoring and debugging

These improvements significantly enhance the security posture of the application by addressing common vulnerabilities like injection attacks, DoS, information leakage, and providing robust error handling that doesn't expose sensitive information.

