// Test script to verify credentials from .env.test
// NOTE: This script is for educational purposes only.
// In production, never commit credentials or test them in this manner.

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const axios = require('axios');

// Load environment variables
const config = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

console.log('Testing credentials from .env.test...');
console.log('====================================');

// Helper to mask sensitive values in logs
const maskValue = (value) => {
  if (!value) return '<not set>';
  if (value.length <= 8) return '*'.repeat(value.length);
  return value.substring(0, 4) + '*'.repeat(value.length - 8) + value.substring(value.length - 4);
};

// Test Database Connection
async function testDatabaseConnection() {
  console.log('\n1. Testing Database Connection:');
  console.log(`   DATABASE_URL: ${maskValue(config.DATABASE_URL)}`);

  if (!config.DATABASE_URL) {
    console.log('   ❌ DATABASE_URL not set');
    return false;
  }

  try {
    // Extract connection parameters from URL
    // Format: postgres://user:password@host:port/database
    const url = new URL(config.DATABASE_URL);

    const client = new Client({
      host: url.hostname,
      port: url.port || 5432,
      database: url.pathname.substring(1), // Remove leading '/'
      user: url.username,
      password: url.password,
      ssl: url.protocol === 'postgres:' ? { rejectUnauthorized: false } : undefined,
    });

    await client.connect();
    const res = await client.query('SELECT version()');
    await client.end();

    console.log('   ✅ Database connection successful');
    console.log(`   📊 PostgreSQL version: ${res.rows[0].version.substring(0, 50)}...`);
    return true;
  } catch (error) {
    console.log('   ❌ Database connection failed');
    console.log(`   💥 Error: ${error.message}`);
    return false;
  }
}

// Test AWS Credentials (basic validation only)
function testAWSCredentials() {
  console.log('\n2. Testing AWS Credentials Format:');
  console.log(`   AWS_ACCESS_KEY_ID: ${maskValue(config.AWS_ACCESS_KEY_ID)}`);
  console.log(`   AWS_SECRET_ACCESS_KEY: ${maskValue(config.AWS_SECRET_ACCESS_KEY)}`);

  const accessKeyIdPattern = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyPattern = /^[0-9a-zA-Z/+]{40}$/;

  const accessKeyValid = accessKeyIdPattern.test(config.AWS_ACCESS_KEY_ID || '');
  const secretKeyValid = secretKeyPattern.test(config.AWS_SECRET_ACCESS_KEY || '');

  if (accessKeyValid && secretKeyValid) {
    console.log('   ✔️  AWS credentials appear to be in correct format');
    // Note: We're not actually making AWS API calls here for security reasons
    console.log('   ⚠️  Actual AWS API validation skipped for security');
    return true;
  } else {
    console.log('   ❌ AWS credentials format appears invalid');
    if (!accessKeyValid) console.log('      - Access Key ID format incorrect');
    if (!secretKeyValid) console.log('      - Secret Access Key format incorrect');
    return false;
  }
}

// Test Anthropic API Key (format check)
function testAnthropicAPIKey() {
  console.log('\n3. Testing Anthropic API Key Format:');
  console.log(`   ANTHROPIC_API_KEY: ${maskValue(config.ANTHROPIC_API_KEY)}`);

  if (!config.ANTHROPIC_API_KEY) {
    console.log('   ❌ ANTHROPIC_API_KEY not set');
    return false;
  }

  // Anthropic API keys typically start with 'sk-ant-'
  const anthropicPattern = /^sk-ant-[a-zA-Z0-9\-_]+$/;
  const isValid = anthropicPattern.test(config.ANTHROPIC_API_KEY);

  if (isValid) {
    console.log('   ✔️  Anthropic API key appears to be in correct format');
    // Note: We're not actually making API calls here to avoid potential charges
    console.log('   ⚠️  Actual API validation skipped to prevent charges');
    return true;
  } else {
    console.log('   ❌ Anthropic API key format appears invalid');
    return false;
  }
}

// Test Stripe Secret Key (format check)
function testStripeSecretKey() {
  console.log('\n4. Testing Stripe Secret Key Format:');
  console.log(`   STRIPE_SECRET_KEY: ${maskValue(config.STRIPE_SECRET_KEY)}`);

  if (!config.STRIPE_SECRET_KEY) {
    console.log('   ❌ STRIPE_SECRET_KEY not set');
    return false;
  }

  // Stripe secret keys start with 'sk_live_' or 'sk_test_'
  const stripePattern = /^sk_(live|test)_[a-zA-Z0-9]+$/;
  const isValid = stripePattern.test(config.STRIPE_SECRET_KEY);

  if (isValid) {
    console.log('   ✔️  Stripe secret key appears to be in correct format');
    // Note: We're not actually making API calls here to avoid potential charges
    console.log('   ⚠️  Actual API validation skipped to prevent charges');
    return true;
  } else {
    console.log('   ❌ Stripe secret key format appears invalid');
    return false;
  }
}

// Test Logfire Token (format check)
function testLogfireToken() {
  console.log('\n5. Testing Logfire Token Format:');
  console.log(`   LOGFIRE_TOKEN: ${maskValue(config.LOGFIRE_TOKEN)}`);

  if (!config.LOGFIRE_TOKEN) {
    console.log('   ❌ LOGFIRE_TOKEN not set');
    return false;
  }

  // Simple format check - tokens are usually alphanumeric with dashes
  const tokenPattern = /^[a-zA-Z0-9\-_]+$/;
  const isValid = tokenPattern.test(config.LOGFIRE_TOKEN);

  if (isValid) {
    console.log('   ✔️  Logfire token appears to be in correct format');
    // Note: We're not actually making API calls here
    console.log('   ⚠️  Actual API validation skipped');
    return true;
  } else {
    console.log('   ❌ Logfire token format appears invalid');
    return false;
  }
}

// Main test runner
async function runTests() {
  try {
    // Check if required packages are installed
    const pkg = require('./package.json');
    const hasPg = pkg.dependencies && pkg.dependencies.pg;
    const hasAxios = pkg.dependencies && pkg.dependencies.axios;

    if (!hasPg) {
      console.log('Warning: pg package not found in package.json');
      console.log('Installing pg for database testing...');
      // In a real scenario, we would install it, but we'll skip for safety
    }

    if (!hasAxios) {
      console.log('Warning: axios package not found in package.json');
      console.log('Installing axios for API testing...');
      // In a real scenario, we would install it, but we'll skip for safety
    }

    // Run tests
    const results = [];

    // Test database connection
    results.push(await testDatabaseConnection());

    // Test credential formats
    results.push(testAWSCredentials());
    results.push(testAnthropicAPIKey());
    results.push(testStripeSecretKey());
    results.push(testLogfireToken());

    // Summary
    console.log('\n====================================');
    console.log('TEST SUMMARY');
    console.log('====================================');
    const passed = results.filter(Boolean).length;
    const total = results.length;
    console.log(`Passed: ${passed}/${total}`);

    if (passed === total) {
      console.log('🎉 All tests passed!');
    } else {
      console.log('⚠️  Some tests failed or were skipped');
    }

    return passed === total;
  } catch (error) {
    console.error('💥 Test runner failed:', error);
    return false;
  }
}

// Run tests if this file is executed directly
if (require.main === module) {
  runTests().then(success => {
    process.exit(success ? 0 : 1);
  }).catch(err => {
    console.error('Failed to run tests:', err);
    process.exit(1);
  });
}

module.exports = { runTests };

{
