// Simple credential validation script
// Checks format and basic validity without making external calls

require('dotenv').config({ path: '.env.test' });

console.log('Checking credentials from .env.test...');
console.log('====================================');

// Load environment variables
const env = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

// Helper to mask sensitive values in logs
const maskValue = (value) => {
  if (!value) return '<not set>';
  if (value.length <= 8) return '*'.repeat(value.length);
  return value.substring(0, 4) + '*'.repeat(value.length - 8) + value.substring(value.length - 4);
};

// Validation functions
function validateDatabaseUrl(url) {
  if (!url) return { valid: false, reason: 'DATABASE_URL not set' };

  try {
    const parsed = new URL(url);
    if (parsed.protocol !== 'postgres:') {
      return { valid: false, reason: 'Protocol must be postgres:' };
    }
    if (!parsed.hostname) return { valid: false, reason: 'Hostname missing' };
    if (!parsed.pathname || parsed.pathname === '/') {
      return { valid: false, reason: 'Database name missing' };
    }
    return { valid: true, reason: 'URL format is valid' };
  } catch (e) {
    return { valid: false, reason: 'Invalid URL format' };
  }
}

function validateAWSKeys(accessKey, secretKey) {
  const results = {};

  if (!accessKey) {
    results.accessKeyId = { valid: false, reason: 'AWS_ACCESS_KEY_ID not set' };
  } else {
    // AWS access keys are 20 characters: AKIA followed by 16 alphanumeric chars
    const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    results.accessKeyId = {
      valid: accessKeyPattern.test(accessKey),
      reason: accessKeyPattern.test(accessKey) 
        ? 'Format appears valid' 
        : 'Should be AKIA followed by 16 alphanumeric characters'
    };
  }

  if (!secretKey) {
    results.secretAccessKey = { valid: false, reason: 'AWS_SECRET_ACCESS_KEY not set' };
  } else {
    // AWS secret keys are 40 characters: alphanumeric, +, /
    const secretKeyPattern = /^[0-9a-zA-Z\+/]{40}$/;
    results.secretAccessKey = {
      valid: secretKeyPattern.test(secretKey),
      reason: secretKeyPattern.test(secretKey)
        ? 'Format appears valid'
        : 'Should be 40 alphanumeric, +, / characters'
    };
  }

  return results;
}

function validateAnthropicKey(key) {
  if (!key) return { valid: false, reason: 'ANTHROPIC_API_KEY not set' };

  // Anthropic API keys typically start with 'sk-ant-' followed by alphanumeric and hyphens/underscores
  const pattern = /^sk-ant-[a-zA-Z0-9\-_]+$/;
  return {
    valid: pattern.test(key),
    reason: pattern.test(key)
      ? 'Format appears valid'
      : 'Should start with sk-ant- followed by alphanumeric, hyphens, underscores'
  };
}

function validateStripeKey(key) {
  if (!key) return { valid: false, reason: 'STRIPE_SECRET_KEY not set' };

  // Stripe secret keys: sk_live_ or sk_test_ followed by alphanumeric
  const pattern = /^sk_(live|test)_[a-zA-Z0-9]+$/;
  return {
    valid: pattern.test(key),
    reason: pattern.test(key)
      ? 'Format appears valid'
      : 'Should start with sk_live_ or sk_test_ followed by alphanumeric characters'
  };
}

function validateLogfireToken(token) {
  if (!token) return { valid: false, reason: 'LOGFIRE_TOKEN not set' };

  // Simple check: alphanumeric, hyphens, underscores
  const pattern = /^[a-zA-Z0-9\-_]+$/;
  return {
    valid: pattern.test(token),
    reason: pattern.test(token)
      ? 'Format appears valid'
      : 'Should contain only alphanumeric characters, hyphens, and underscores'
  };
}

// Run validations
console.log('\n1. DATABASE_URL:');
console.log(`   Value: ${maskValue(env.DATABASE_URL)}`);
const dbResult = validateDatabaseUrl(env.DATABASE_URL);
console.log(`   Status: ${dbResult.valid ? '✅ VALID' : '❌ INVALID'}`);
if (!dbResult.valid) console.log(`   Reason: ${dbResult.reason}`);

console.log('\n2. AWS Credentials:');
console.log(`   AWS_ACCESS_KEY_ID: ${maskValue(env.AWS_ACCESS_KEY_ID)}`);
console.log(`   AWS_SECRET_ACCESS_KEY: ${maskValue(env.AWS_SECRET_ACCESS_KEY)}`);
const awsResults = validateAWSKeys(env.AWS_ACCESS_KEY_ID, env.AWS_SECRET_ACCESS_KEY);
console.log(`   Access Key ID: ${awsResults.accessKeyId.valid ? '✅ VALID' : '❌ INVALID'} - ${awsResults.accessKeyId.reason}`);
console.log(`   Secret Access Key: ${awsResults.secretAccessKey.valid ? '✅ VALID' : '❌ INVALID'} - ${awsResults.secretAccessKey.reason}`);

console.log('\n3. ANTHROPIC_API_KEY:');
console.log(`   Value: ${maskValue(env.ANTHROPIC_API_KEY)}`);
const anthropicResult = validateAnthropicKey(env.ANTHROPIC_API_KEY);
console.log(`   Status: ${anthropicResult.valid ? '✅ VALID' : '❌ INVALID'}`);
if (!anthropicResult.valid) console.log(`   Reason: ${anthropicResult.reason}`);

console.log('\n4. STRIPE_SECRET_KEY:');
console.log(`   Value: ${maskValue(env.STRIPE_SECRET_KEY)}`);
const stripeResult = validateStripeKey(env.STRIPE_SECRET_KEY);
console.log(`   Status: ${stripeResult.valid ? '✅ VALID' : '❌ INVALID'}`);
if (!stripeResult.valid) console.log(`   Reason: ${stripeResult.reason}`);

console.log('\n5. LOGFIRE_TOKEN:');
console.log(`   Value: ${maskValue(env.LOGFIRE_TOKEN)}`);
const logfireResult = validateLogfireToken(env.LOGFIRE_TOKEN);
console.log(`   Status: ${logfireResult.valid ? '✅ VALID' : '❌ INVALID'}`);
if (!logfireResult.valid) console.log(`   Reason: ${logfireResult.reason}`);

// Summary
console.log('\n====================================');
console.log('VALIDATION SUMMARY');
console.log('====================================');

const allResults = [
  { name: 'DATABASE_URL', valid: dbResult.valid },
  { name: 'AWS_ACCESS_KEY_ID', valid: awsResults.accessKeyId.valid },
  { name: 'AWS_SECRET_ACCESS_KEY', valid: awsResults.secretAccessKey.valid },
  { name: 'ANTHROPIC_API_KEY', valid: anthropicResult.valid },
  { name: 'STRIPE_SECRET_KEY', valid: stripeResult.valid },
  { name: 'LOGFIRE_TOKEN', valid: logfireResult.valid }
];

const passed = allResults.filter(r => r.valid).length;
const total = allResults.length;

allResults.forEach(result => {
  console.log(`${result.name}: ${result.valid ? '✅ PASS' : '❌ FAIL'}`);
});

console.log(`\nOverall: ${passed}/${total} checks passed`);

if (passed === total) {
  console.log('\n🎉 All credential format checks passed!');
  console.log('⚠️  Note: This only validates format, not actual service connectivity.');
} else {
  console.log(`\n⚠️  ${total - passed} format check(es) failed.`);
  console.log('These credentials may be stale or incorrectly formatted.');
}

// Manual environment variable checking without external dependencies
// Parses .env.test file directly

const fs = require('fs');

console.log('Manually checking credentials in .env.test...');
console.log('====================================');

// Read and parse .env.test file manually
function parseEnvFile(filePath) {
  const env = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
      // Remove comments and trim
      const cleanLine = line.split('#')[0].trim();

      // Skip empty lines
      if (!cleanLine) return;

      // Parse KEY=VALUE format
      const match = cleanLine.match(/^([A-Z_][A-Z0-9_]*)=(.*)$/);
      if (match) {
        let key = match[1];
        let value = match[2];

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) || 
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        env[key] = value;
      }
    });

    return env;
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
    return {};
  }
}

// Load environment variables from .env.test
const env = parseEnvFile('.env.test');

console.log(`Loaded ${Object.keys(env).length} environment variables from .env.test`);
console.log();

// Helper to mask sensitive values in logs
const maskValue = (value) => {
  if (!value) return '<not set>';
  if (value.length <= 8) return '*'.repeat(value.length);
  return value.substring(0, 4) + '*'.repeat(value.length - 8) + value.substring(value.length - 4);
};

// Validation functions (same as before but without external deps)
function validateDatabaseUrl(url) {
  if (!url) return { valid: false, reason: 'DATABASE_URL not set' };

  try {
    const parsed = new URL(url);
    if (parsed.protocol !== 'postgres:') {
      return { valid: false, reason: 'Protocol must be postgres:' };
    }
    if (!parsed.hostname) return { valid: false, reason: 'Hostname missing' };
    if (!parsed.pathname || parsed.pathname === '/') {
      return { valid: false, reason: 'Database name missing' };
    }
    return { valid: true, reason: 'URL format is valid' };
  } catch (e) {
    return { valid: false, reason: 'Invalid URL format' };
  }
}

function validateAWSKeys(accessKey, secretKey) {
  const results = {};

  if (!accessKey) {
    results.accessKeyId = { valid: false, reason: 'AWS_ACCESS_KEY_ID not set' };
  } else {
    // AWS access keys are 20 characters: AKIA followed by 16 alphanumeric chars
    const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    results.accessKeyId = {
      valid: accessKeyPattern.test(accessKey),
      reason: accessKeyPattern.test(accessKey) 
        ? 'Format appears valid' 
        : 'Should be AKIA followed by 16 alphanumeric characters'
    };
  }

  if (!secretKey) {
    results.secretAccessKey = { valid: false, reason: 'AWS_SECRET_ACCESS_KEY not set' };
  } else {
    // AWS secret keys are 40 characters: alphanumeric, +, /
    const secretKeyPattern = /^[0-9a-zA-Z\+/]{40}$/;
    results.secretAccessKey = {
      valid: secretKeyPattern.test(secretKey),
      reason: secretKeyPattern.test(secretKey)
        ? 'Format appears valid'
        : 'Should be 40 alphanumeric, +, / characters'
    };
  }

  return results;
}

function validateAnthropicKey(key) {
  if (!key) return { valid: false, reason: 'ANTHROPIC_API_KEY not set' };

  // Anthropic API keys typically start with 'sk-ant-' followed by alphanumeric and hyphens/underscores
  const pattern = /^sk-ant-[a-zA-Z0-9\-_]+$/;
  return {
    valid: pattern.test(key),
    reason: pattern.test(key)
      ? 'Format appears valid'
      : 'Should start with sk-ant- followed by alphanumeric, hyphens, underscores'
  };
}

function validateStripeKey(key) {
  if (!key) return { valid: false, reason: 'STRIPE_SECRET_KEY not set' };

  // Stripe secret keys: sk_live_ or sk_test_ followed by alphanumeric
  const pattern = /^sk_(live|test)_[a-zA-Z0-9]+$/;
  return {
    valid: pattern.test(key),
    reason: pattern.test(key)
      ? 'Format appears valid'
      : 'Should start with sk_live_ or sk_test_ followed by alphanumeric characters'
  };
}

function validateLogfireToken(token) {
  if (!token) return { valid: false, reason: 'LOGFIRE_TOKEN not set' };

  // Simple check: alphanumeric, hyphens, underscores
  const pattern = /^[a-zA-Z0-9\-_]+$/;
  return {
    valid: pattern.test(token),
    reason: pattern.test(token)
      ? 'Format appears valid'
      : 'Should contain only alphanumeric characters, hyphens, and underscores'
  };
}

// Get values from parsed env
const getEnvValue = (key) => env[key] || null;

// Run validations
console.log('1. DATABASE_URL:');
console.log(`   Value: ${maskValue(getEnvValue('DATABASE_URL'))}`);
const dbResult = validateDatabaseUrl(getEnvValue('DATABASE_URL'));
console.log(`   Status: ${dbResult.valid ? '✅ VALID' : '❌ INVALID'}`);
if (!dbResult.valid) console.log(`   Reason: ${dbResult.reason}`);

console.log('\n2. AWS Credentials:');
console.log(`   AWS_ACCESS_KEY_ID: ${maskValue(getEnvValue('AWS_ACCESS_KEY_ID'))}`);
console.log(`   AWS_SECRET_ACCESS_KEY: ${maskValue(getEnvValue('AWS_SECRET_ACCESS_KEY'))}`);
const awsResults = validateAWSKeys(getEnvValue('AWS_ACCESS_KEY_ID'), getEnvValue('AWS_SECRET_ACCESS_KEY'));
console.log(`   Access Key ID: ${awsResults.accessKeyId.valid ? '✅ VALID' : '❌ INVALID'} - ${awsResults.accessKeyId.reason}`);
console.log(`   Secret Access Key: ${awsResults.secretAccessKey.valid ? '✅ VALID' : '❌ INVALID'} - ${awsResults.secretAccessKey.reason}`);

console.log('\n3. ANTHROPIC_API_KEY:');
console.log(`   Value: ${maskValue(getEnvValue('ANTHROPIC_API_KEY'))}`);
const anthropicResult = validateAnthropicKey(getEnvValue('ANTHROPIC_API_KEY'));
console.log(`   Status: ${anthropicResult.valid ? '✅ VALID' : '❌ INVALID'}`);
if (!anthropicResult.valid) console.log(`   Reason: ${anthropicResult.reason}`);

console.log('\n4. STRIPE_SECRET_KEY:');
console.log(`   Value: ${maskValue(getEnvValue('STRIPE_SECRET_KEY'))}`);
const stripeResult = validateStripeKey(getEnvValue('STRIPE_SECRET_KEY'));
console.log(`   Status: ${stripeResult.valid ? '✅ VALID' : '❌ INVALID'}`);
if (!stripeResult.valid) console.log(`   Reason: ${stripeResult.reason}`);

console.log('\n5. LOGFIRE_TOKEN:');
console.log(`   Value: ${maskValue(getEnvValue('LOGFIRE_TOKEN'))}`);
const logfireResult = validateLogfireToken(getEnvValue('LOGFIRE_TOKEN'));
console.log(`   Status: ${logfireResult.valid ? '✅ VALID' : '❌ INVALID'}`);
if (!logfireResult.valid) console.log(`   Reason: ${logfireResult.reason}`);

// Summary
console.log('\n====================================');
console.log('VALIDATION SUMMARY');
console.log('====================================');

const allResults = [
  { name: 'DATABASE_URL', valid: dbResult.valid },
  { name: 'AWS_ACCESS_KEY_ID', valid: awsResults.accessKeyId.valid },
  { name: 'AWS_SECRET_ACCESS_KEY', valid: awsResults.secretAccessKey.valid },
  { name: 'ANTHROPIC_API_KEY', valid: anthropicResult.valid },
  { name: 'STRIPE_SECRET_KEY', valid: stripeResult.valid },
  { name: 'LOGFIRE_TOKEN', valid: logfireResult.valid }
];

const passed = allResults.filter(r => r.valid).length;
const total = allResults.length;

allResults.forEach(result => {
  console.log(`${result.name}: ${result.valid ? '✅ PASS' : '❌ FAIL'}`);
});

console.log(`\nOverall: ${passed}/${total} checks passed`);

// Detailed analysis
console.log('\n====================================');
console.log('DETAILED ANALYSIS');
console.log('====================================');

if (!dbResult.valid) {
  console.log('❌ DATABASE_URL issues:');
  console.log(`   ${dbResult.reason}`);

  const url = getEnvValue('DATABASE_URL');
  if (url) {
    try {
      const parsed = new URL(url);
      console.log(`   Parsed components:`);
      console.log(`     Protocol: ${parsed.protocol}`);
      console.log(`     Hostname: ${parsed.hostname || '<missing>'}`);
      console.log(`     Port: ${parsed.port || '<default>'}`);
      console.log(`     Username: ${parsed.username || '<missing>'}`);
      console.log(`     Password: ${parsed.password ? '<present>' : '<missing>'}`);
      console.log(`     Database: ${parsed.pathname ? parsed.pathname.substring(1) : '<missing>'}`);
    } catch (e) {
      console.log(`   Failed to parse as URL: ${e.message}`);
    }
  }
}

const awsAccessKey = getEnvValue('AWS_ACCESS_KEY_ID');
const awsSecretKey = getEnvValue('AWS_SECRET_ACCESS_KEY');

if (awsAccessKey && !awsResults.accessKeyId.valid) {
  console.log('❌ AWS_ACCESS_KEY_ID issues:');
  console.log(`   Value: ${awsAccessKey}`);
  console.log(`   Length: ${awsAccessKey.length} chars`);
  console.log(`   Starts with AKIA: ${awsAccessKey.startsWith('AKIA')}`);
  if (awsAccessKey.startsWith('AKIA')) {
    console.log(`   Remaining chars: ${awsAccessKey.substring(4)} (should be 16 alphanumeric)`);
  }
}

if (awsSecretKey && !awsResults.secretAccessKey.valid) {
  console.log('❌ AWS_SECRET_ACCESS_KEY issues:');
  console.log(`   Length: ${awsSecretKey.length} chars (should be 40)`);
  const validChars = /^[0-9a-zA-Z\+/]+$/.test(awsSecretKey);
  console.log(`   Contains only valid chars (a-z, A-Z, 0-9, +, /): ${validChars}`);
}

if (!anthropicResult.valid) {
  console.log('❌ ANTHROPIC_API_KEY issues:');
  const key = getEnvValue('ANTHROPIC_API_KEY');
  console.log(`   Value: ${maskValue(key)}`);
  console.log(`   Starts with sk-ant-: ${key ? key.startsWith('sk-ant-') : false}`);
}

if (!stripeResult.valid) {
  console.log('❌ STRIPE_SECRET_KEY issues:');
  const key = getEnvValue('STRIPE_SECRET_KEY');
  console.log(`   Value: ${maskValue(key)}`);
  console.log(`   Starts with sk_live_ or sk_test_: ${key ? (key.startsWith('sk_live_') || key.startsWith('sk_test_')) : false}`);
}

if (!logfireResult.valid) {
  console.log('❌ LOGFIRE_TOKEN issues:');
  const token = getEnvValue('LOGFIRE_TOKEN');
  console.log(`   Value: ${maskValue(token)}`);
  const validChars = /^[a-zA-Z0-9\-_]+$/.test(token || '');
  console.log(`   Contains only alphanumeric, hyphen, underscore: ${validChars}`);
}

if (passed === total) {
  console.log('\n🎉 All credential format checks passed!');
  console.log('⚠️  Note: This only validates format, not actual service connectivity.');
  console.log('⚠️  The values in .env.test are marked as CANARY values, which are likely');
  console.log('     intentionally invalid/test values for security testing purposes.');
} else {
  console.log(`\n⚠️  ${total - passed} format check(es) failed.`);
  console.log('These credentials appear to be stale, incorrectly formatted, or');
  console.log('intentionally invalid (as suggested by the CANARY markings).');
}

// Show what we actually found in the file
console.log('\n====================================');
console.log('ACTUAL VALUES FOUND IN .env.test');
console.log('====================================');

Object.keys(env).forEach(key => {
  console.log(`${key}=${maskValue(env[key])}`);
});

