// Improved application with proper error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const logger = require('morgan');
const { validationResult, body, param, query } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS
app.use(xss()); // Sanitize user input from XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
});
app.use(limiter);

// Body parsing
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Logging
app.use(logger('dev'));

// Health check endpoint with validation
app.get('/health', 
  [
    // Validate query parameters if any
    query('detailed').optional().isBoolean().toBoolean()
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    // Add detailed info if requested
    if (req.query.detailed) {
      response.memoryUsage = process.memoryUsage();
      response.nodeVersion = process.version;
    }

    res.json(response);
  }
);

// Users endpoint with validation
app.get('/users',
  [
    // Validate query parameters
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('offset').optional().isInt({ min: 0 }).toInt(),
    query('sort').optional().isIn(['id', 'name', 'email']),
    query('order').optional().isIn(['asc', 'desc'])
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    // Sample data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Apply filtering, sorting, and pagination
    let filteredUsers = [...users];

    // Apply sorting
    if (req.query.sort) {
      const sortField = req.query.sort;
      const sortOrder = req.query.order || 'asc';
      filteredUsers.sort((a, b) => {
        if (a[sortField] < b[sortField]) return sortOrder === 'asc' ? -1 : 1;
        if (a[sortField] > b[sortField]) return sortOrder === 'asc' ? 1 : -1;
        return 0;
      });
    }

    // Apply pagination
    const offset = req.query.offset || 0;
    const limit = req.query.limit || filteredUsers.length;
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      count: filteredUsers.length,
      offset: offset,
      limit: limit,
      data: paginatedUsers
    });
  }
);

// Individual user endpoint with parameter validation
app.get('/users/:id',
  [
    // Validate route parameter
    param('id').isInt({ min: 1 }).toInt()
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    const userId = req.params.id;

    // Sample data lookup (in real app, this would query a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  }
);

// POST endpoint to create a user with comprehensive validation
app.post('/users',
  [
    // Validate and sanitize input
    body('name').trim().isLength({ min: 2, max: 50 }).escape()
      .withMessage('Name must be between 2 and 50 characters'),
    body('email').trim().isEmail().normalizeEmail()
      .withMessage('Please provide a valid email address'),
    body('age').optional().isInt({ min: 0, max: 150 }).toInt()
      .withMessage('Age must be a number between 0 and 150')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    }

    // In a real application, you would save the user to a database
    const newUser = {
      id: Date.now(), // Simple ID generation for demo
      name: req.body.name,
      email: req.body.email,
      age: req.body.age,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });
  }
);

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // Determine response message based on environment
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message || 'Internal Server Error';

  res.status(statusCode).json({
    error: message,
    // Only include stack trace in development
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception thrown:', error);
  // Graceful shutdown logic
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

/**
 * Test suite for the enhanced Express.js application
 * Demonstrates testing of validation and error handling
 */

const request = require('supertest');
const app = require('./app');

describe('Health Endpoint', () => {
  test('should return 200 OK for basic health check', async () => {
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('status', 'ok');
    expect(response.body).toHaveProperty('timestamp');
  });

  test('should return detailed info when requested', async () => {
    const response = await request(app)
      .get('/health')
      .query({ detailed: 'true' });

    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('memoryUsage');
    expect(response.body).toHaveProperty('nodeVersion');
  });

  test('should validate query parameters', async () => {
    const response = await request(app)
      .get('/health')
      .query({ detailed: 'invalid' }); // Should be boolean

    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Validation failed');
  });
});

describe('Users Endpoint', () => {
  test('should return list of users', async () => {
    const response = await request(app).get('/users');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('data');
    expect(Array.isArray(response.body.data)).toBe(true);
  });

  test('should validate pagination parameters', async () => {
    const response = await request(app)
      .get('/users')
      .query({ limit: 'invalid' }); // Should be integer

    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Validation failed');
  });

  test('should validate sort parameters', async () => {
    const response = await request(app)
      .get('/users')
      .query({ sort: 'invalidField' }); // Not in allowed list

    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Validation failed');
  });

  test('should return single user by valid ID', async () => {
    const response = await request(app).get('/users/1');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('id', 1);
    expect(response.body).toHaveProperty('name', 'Alice');
  });

  test('should validate user ID parameter', async () => {
    const response = await request(app).get('/users/invalid');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Validation failed');
  });

  test('should return 404 for non-existent user', async () => {
    const response = await request(app).get('/users/999');
    expect(response.status).toBe(404);
    expect(response.body).toHaveProperty('error', 'User not found');
  });
});

describe('User Creation Endpoint', () => {
  test('should create a user with valid data', async () => {
    const userData = {
      name: 'John Doe',
      email: 'john@example.com',
      age: 30
    };

    const response = await request(app)
      .post('/users')
      .send(userData);

    expect(response.status).toBe(201);
    expect(response.body).toHaveProperty('message', 'User created successfully');
    expect(response.body.user).toHaveProperty('name', 'John Doe');
    expect(response.body.user).toHaveProperty('email', 'john@example.com');
  });

  test('should validate name field', async () => {
    const userData = {
      name: 'J', // Too short (min 2 chars)
