// Improved application with enhanced error handling, input validation, and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validate } = require('express-validation');
const Joi = require('joi');

// Create Express app
const app = express();

// Security middleware
app.use(helmet()); // Sets various security headers
app.use(express.json()); // Parse JSON bodies

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Input validation schemas
const userQuerySchema = {
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).default(10),
    offset: Joi.number().integer().min(0).default(0),
    sort: Joi.string().valid('id', 'name', 'email').default('id'),
    order: Joi.string().valid('asc', 'desc').default('asc')
  })
};

const userIdParamSchema = {
  params: Joi.object({
    id: Joi.number().integer().positive.required()
  })
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Get users endpoint with validation
app.get('/users', validate(userQuerySchema), (req, res) => {
  try {
    // In a real application, you would fetch from a database
    // Here we're using mock data with applied filtering/sorting
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    const { limit, offset, sort, order } = req.query;

    // Apply sorting
    const sortedUsers = [...users].sort((a, b) => {
      if (a[sort] < b[sort]) return order === 'asc' ? -1 : 1;
      if (a[sort] > b[sort]) return order === 'asc' ? 1 : -1;
      return 0;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
        hasMore: offset + limit < users.length
      }
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Get specific user by ID with validation
app.get('/users/:id', validate(userIdParamSchema), (req, res) => {
  try {
    const { id } = req.params;

    // In a real application, you would fetch from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    const user = users.find(u => u.id === parseInt(id));

    if (!user) {
      return res.status(404).json({ 
        error: 'Not found',
        message: `User with ID ${id} not found`
      });
    }

    res.json({ data: user });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
