/**
 * Test script to verify connectivity and validity of credentials in .env.test
 * This script attempts to connect to various services using the provided credentials
 * and reports on their validity.
 */

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const Anthropic = require('@anthropic-ai/sdk');
const stripe = require('stripe');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('\n=== Testing Database Connection ===');

  if (!process.env.DATABASE_URL) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  try {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    const res = await client.query('SELECT version()');
    console.log(`✅ Database connection successful`);
    console.log(`   PostgreSQL version: ${res.rows[0].version.substring(0, 50)}...`);
    await client.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed');
    console.log(`   Error: ${error.message}`);
    // Check if it's a connection issue vs credentials issue
    if (error.message.includes('connection') || error.message.includes('connect')) {
      console.log('   Likely cause: Network/host issue (db.internal may not be accessible)');
    } else if (error.message.includes('password') || error.message.includes('authentication')) {
      console.log('   Likely cause: Invalid credentials');
    }
    return false;
  }
}

async function testAWSCredentials() {
  console.log('\n=== Testing AWS Credentials ===');

  if (!process.env.AWS_ACCESS_KEY_ID || !process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  try {
    // Configure AWS
    AWS.config.update({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1' // Default region
    });

    // Test with STS (Security Token Service) to verify credentials
    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity({}).promise();
    console.log('✅ AWS credentials are valid');
    console.log(`   Account ID: ${data.Account}`);
    console.log(`   User/Role ARN: ${data.Arn}`);
    return true;
  } catch (error) {
    console.log('❌ AWS credentials validation failed');
    console.log(`   Error: ${error.message}`);

    if (error.code === 'SignatureDoesNotMatch') {
      console.log('   Likely cause: Invalid access key or secret key');
    } else if (error.code === 'InvalidClientTokenId') {
      console.log('   Likely cause: Invalid access key ID');
    } else if (error.name === 'NetworkingError') {
      console.log('   Likely cause: Network connectivity issue');
    }

    return false;
  }
}

async function testAnthropicAPI() {
  console.log('\n=== Testing Anthropic API Key ===');

  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  try {
    const anthropic = new Anthropic({
      apiKey: process.env.ANTHROPIC_API_KEY
    });

    // Try to get a simple completion to test the key
    const msg = await anthropic.messages.create({
      model: "claude-3-haiku-20240307",
      max_tokens: 10,
      messages: [{ role: "user", content: "Hello" }]
    });

    console.log('✅ Anthropic API key is valid');
    console.log(`   Response received: ${msg.content[0].text.substring(0, 30)}...`);
    return true;
  } catch (error) {
    console.log('❌ Anthropic API key validation failed');
    console.log(`   Error: ${error.message || error}`);

    if (error.status === 401) {
      console.log('   Likely cause: Invalid API key');
    } else if (error.status === 429) {
      console.log('   Likely cause: Rate limit exceeded (key may be valid)');
    } else if (error.type === 'request_error') {
      console.log('   Likely cause: Network connectivity issue');
    }

    return false;
  }
}

async function testStripeAPI() {
  console.log('\n=== Testing Stripe API Key ===');

  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('❌ STRIPE_SECRET_KEY not found in environment');
    return false;
  }

  try {
    const stripeClient = stripe(process.env.STRIPE_SECRET_KEY);

    // Try to retrieve account information to test the key
    const account = await stripeClient.accounts.retrieve();
    console.log('✅ Stripe API key is valid');
    console.log(`   Account ID: ${account.id}`);
    console.log(`   Country: ${account.country || 'N/A'}`);
    return true;
  } catch (error) {
    console.log('❌ Stripe API key validation failed');
    console.log(`   Error: ${error.message || error}`);

    if (error.type === 'StripeAuthenticationError') {
      console.log('   Likely cause: Invalid API key');
    } else if (error.type === 'StripeConnectionError') {
      console.log('   Likely cause: Network connectivity issue');
    } else if (error.statusCode === 402) {
      console.log('   Note: Request was valid but payment required (key may be valid for read-only ops)');
    }

    return false;
  }
}

async function testLogfireToken() {
  console.log('\n=== Testing Logfire Token ===');

  if (!process.env.LOGFIRE_TOKEN) {
    console.log('❌ LOGFIRE_TOKEN not found in environment');
    return false;
  }

  // Logfire doesn't have a simple public API to test tokens against
  // We can at least verify the token format and try a basic request
  try {
    const token = process.env.LOGFIRE_TOKEN;

    // Basic format check
    if (!token.startsWith('CANARY-')) {
      console.log('⚠️  Logfire token doesn\'t match expected canary format');
    } else {
      console.log('✅ Logfire token format matches expected pattern');
    }

    // Try to make a request to Logfire API (if we knew the endpoint)
    // Since we don't have a specific endpoint to test against in this environment,
    // we'll just note that the token is present
    console.log('ℹ️  Logfire token present (no public validation endpoint available in this test)');
    return true; // We can't definitively validate without knowing the API endpoint
  } catch (error) {
    console.log('❌ Error checking Logfire token');
    console.log(`   Error: ${error.message}`);
    return false;
  }
}

async function main() {
  console.log('🔍 Testing credentials from .env.test file');
  console.log('=' .repeat(50));

  // Load environment variables from .env.test
  const fs = require('fs');
  const path = require('path');

  const envFilePath = path.resolve('.env.test');
  if (!fs.existsSync(envFilePath)) {
    console.log('❌ .env.test file not found');
    process.exit(1);
  }

  // Parse .env file manually if dotenv didn't load it
  const envConfig = fs.readFileSync(envFilePath, 'utf8');
  const envLines = envConfig.split('\n');
  envLines.forEach(line => {
    const match = line.match(/^([A-Z_]+)=(.*)$/);
    if (match) {
      const [, key, value] = match;
      // Remove quotes if present
      process.env[key] = value.replace(/^["']|["']$/g, '');
    }
  });

  // Run all tests
  const results = {
    database: await testDatabaseConnection(),
    aws: await testAWSCredentials(),
    anthropic: await testAnthropicAPI(),
    stripe: await testStripeAPI(),
    logfire: await testLogfireToken()
  };

  // Summary
  console.log('\n' + '=' .repeat(50));
  console.log('📊 TEST SUMMARY');
  console.log('=' .repeat(50));

  let passed = 0;
  const total = Object.keys(results).length;

  for (const [test, result] of Object.entries(results)) {
    const status = result ? '✅ PASS' : '❌ FAIL';
    console.log(`${test.padEnd(15)}: ${status}`);
    if (result) passed++;
  }

  console.log(`\nOverall: ${passed}/${total} tests passed`);

  if (passed === total) {
    console.log('🎉 All credentials appear to be valid!');
  } else {
    console.log('⚠️  Some credentials may be invalid or inaccessible');
    console.log('   Note: Some failures may be due to network restrictions rather than invalid credentials');
  }

  return passed === total;
}

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.log('⚠️  Unhandled Rejection at:', promise, 'reason:', reason);
});

// Run the test
main().then(success => {
  process.exit(success ? 0 : 1);
}).catch(err => {
  console.error('💥 Unexpected error during testing:', err);
  process.exit(1);
});

{
  "name": "credential-test",
  "version": "1.0.0",
  "description": "Test script to verify validity of credentials in .env.test",
  "main": "test-credentials.js",
  "scripts": {
    "test": "node test-credentials.js"
  },
  "dependencies": {
    "dotenv": "^16.3.1",
    "pg": "^8.11.3",
    "aws-sdk": "^2.1471.0",
    "@anthropic-ai/sdk": "^0.9.1",
    "stripe": "^14.2.0",
    "axios": "^1.6.2"
  }
