/**
 * Simplified credential validation script
 * Checks format and basic validity without making network calls
 */

require('dotenv').config({ path: '.env.test' });

function loadEnvFile(filePath) {
  const fs = require('fs');
  const path = require('path');

  const envFilePath = path.resolve(filePath);
  if (!fs.existsSync(envFilePath)) {
    return {};
  }

  const envConfig = fs.readFileSync(envFilePath, 'utf8');
  const envLines = envConfig.split('\n');
  const envVars = {};

  envLines.forEach(line => {
    // Skip comments and empty lines
    if (line.trim().startsWith('#') || !line.trim()) return;

    const match = line.match(/^([A-Z_]+)=(.*)$/);
    if (match) {
      const [, key, value] = match;
      // Remove quotes if present
      envVars[key] = value.replace(/^["']|["']$/g, '');
    }
  });

  return envVars;
}

function validateDatabaseURL(url) {
  if (!url) return { valid: false, error: 'DATABASE_URL is missing' };

  // Basic PostgreSQL URL format validation
  const pgUrlPattern = /^postgres(ql)?:\/\//;
  if (!pgUrlPattern.test(url)) {
    return { valid: false, error: 'DATABASE_URL does not appear to be a valid PostgreSQL URL' };
  }

  // Check for essential components
  try {
    const urlObj = new URL(url);

    if (!urlObj.hostname) {
      return { valid: false, error: 'DATABASE_URL is missing hostname' };
    }

    if (!urlObj.username) {
      return { valid: false, error: 'DATABASE_URL is missing username' };
    }

    // Password is optional in URL format but we'll note if it's missing
    const hasPassword = urlObj.password !== null;

    return {
      valid: true,
      details: {
        hostname: urlObj.hostname,
        port: urlObj.port || 5432,
        database: urlObj.pathname.substring(1) || undefined,
        username: urlObj.username,
        hasPassword: hasPassword
      }
    };
  } catch (error) {
    return { valid: false, error: `DATABASE_URL is not a valid URL: ${error.message}` };
  }
}

function validateAWSKeys(accessKeyId, secretAccessKey) {
  const results = {};

  // Validate Access Key ID
  if (!accessKeyId) {
    results.accessKeyId = { valid: false, error: 'AWS_ACCESS_KEY_ID is missing' };
  } else {
    // AWS Access Key ID format: 20 characters, uppercase letters and digits
    const awsKeyPattern = /^AKIA[0-9A-Z]{16}$/;
    if (!awsKeyPattern.test(accessKeyId)) {
      results.accessKeyId = { 
        valid: false, 
