const fs = require('fs');
const path = require('path');

// Read .env.test file
function loadEnvFile(filePath) {
  const envPath = path.resolve(filePath);
  if (!fs.existsSync(envPath)) {
    console.log(`❌ Environment file not found: ${envPath}`);
    return null;
  }

  const content = fs.readFileSync(envPath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#') && line.includes('=')) {
      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=');
      envVars[key.trim()] = value.trim();
    }
  });

  return envVars;
}

// Validate PostgreSQL connection string format
function validateDatabaseUrl(url) {
  if (!url) return { valid: false, reason: 'Missing DATABASE_URL' };

  const pgPattern = /^postgres(ql)?:\/\//;
  if (!pgPattern.test(url)) {
    return { valid: false, reason: 'Invalid PostgreSQL URL format' };
  }

  // Basic structure check
  if (!url.includes('@') || !url.includes(':')) {
    return { valid: false, reason: 'Missing required components in URL' };
  }

  return { valid: true, reason: 'Format appears valid' };
}

// Validate AWS credentials
function validateAwsCredentials(accessKeyId, secretAccessKey) {
  if (!accessKeyId) return { valid: false, reason: 'Missing AWS_ACCESS_KEY_ID' };
  if (!secretAccessKey) return { valid: false, reason: 'Missing AWS_SECRET_ACCESS_KEY' };

  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  if (!accessKeyPattern.test(accessKeyId)) {
    return { valid: false, reason: 'AWS Access Key ID format invalid' };
  }

  if (secretAccessKey.length < 20) {
    return { valid: false, reason: 'AWS Secret Access Key too short' };
  }

  return { valid: true, reason: 'Format appears valid' };
}

// Validate Anthropic API key
function validateAnthropicKey(apiKey) {
  if (!apiKey) return { valid: false, reason: 'Missing ANTHROPIC_API_KEY' };

  if (!apiKey.startsWith('sk-ant-')) {
    return { valid: false, reason: 'Anthropic API key must start with sk-ant-' };
  }

  if (apiKey.length < 30) {
    return { valid: false, reason: 'Anthropic API key too short' };
  }

  return { valid: true, reason: 'Format appears valid' };
}

// Validate Stripe secret key
function validateStripeKey(secretKey) {
  if (!secretKey) return { valid: false, reason: 'Missing STRIPE_SECRET_KEY' };

  if (!secretKey.startsWith('sk_live_') && !secretKey.startsWith('sk_test_')) {
    return { valid: false, reason: 'Stripe key must start with sk_live_ or sk_test_' };
  }

  if (secretKey.length < 20) {
    return { valid: false, reason: 'Stripe secret key too short' };
  }

  return { valid: true, reason: 'Format appears valid' };
