// Improved application with error handling, input validation, and security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validate } = require('express-validation');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Validation schemas
const userQuerySchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
  sortBy: Joi.string().valid('id', 'name', 'email').default('id'),
  order: Joi.string().valid('asc', 'desc').default('asc'),
  search: Joi.string().max(100).allow('', null),
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with validation
app.get('/users', 
  validate({ query: userQuerySchema }), 
  (req, res) => {
    try {
      const { limit, offset, sortBy, order, search } = req.query;

      // Sample data (in real app, this would come from a database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
        { id: 4, name: 'Diana', email: 'diana@example.com' },
        { id: 5, name: 'Eve', email: 'eve@example.com' },
      ];

      // Filter users based on search term
      let filteredUsers = users;
      if (search) {
        const searchLower = search.toLowerCase().trim();
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Sort users
      filteredUsers.sort((a, b) => {
        if (a[sortBy] < b[sortBy]) return order === 'asc' ? -1 : 1;
        if (a[sortBy] > b[sortBy]) return order === 'asc' ? 1 : -1;
        return 0;
      });

      // Paginate results
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: filteredUsers.length,
          returnCount: paginatedUsers.length
        }
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Handle Joi validation errors
  if (err.isJoi) {
    return res.status(400).json({
      error: 'Validation failed',
      details: err.details.map(detail => detail.message)
    });
  }

  // Handle express-validation errors
  if (err.status) {
    return res.status(err.status).json({
      error: err.message || 'Validation error',
      details: err.errors
    });
  }

  // Handle other errors
  res.status(err.status || 500).json({
    error: err.message || 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Start server only if this file is run directly
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

