#!/usr/bin/env node
/*
 * Test script to verify credentials in .env.test
 * NOTE: This script makes actual network requests to external services.
 * Use with caution and ensure you have permission to test these endpoints.
 */

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const axios = require('axios');

// Load environment variables from .env.test
console.log('Testing credentials from .env.test...\n');

// Test Database Connection
async function testDatabaseConnection() {
  console.log('1. Testing Database Connection...');
  try {
    const pool = new Pool({
      connectionString: process.env.DATABASE_URL,
    });

    const client = await pool.connect();
    const res = await client.query('SELECT version()');
    console.log(`   ✓ Database connection successful`);
    console.log(`   PostgreSQL version: ${res.rows[0].version.substring(0, 50)}...`);
    client.release();
    await pool.end();
    return true;
  } catch (error) {
    console.log(`   ✗ Database connection failed: ${error.message}`);
    return false;
  }
}

// Test AWS Credentials (by trying to get caller identity)
async function testAWSCredentials() {
  console.log('\n2. Testing AWS Credentials...');
  try {
    const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');

    const stsClient = new STSClient({
      region: 'us-east-1', // Default region
      credentials: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      }
    });

    const command = new GetCallerIdentityCommand({});
    const response = await stsClient.send(command);
    console.log(`   ✓ AWS credentials valid`);
    console.log(`   Account ID: ${response.Account}`);
    console.log(`   User ARN: ${response.Arn}`);
    return true;
  } catch (error) {
    console.log(`   ✗ AWS credentials invalid: ${error.message}`);
    return false;
  }
}

// Test Anthropic API Key
async function testAnthropicAPIKey() {
  console.log('\n3. Testing Anthropic API Key...');
  try {
    const response = await axios.post(
      'https://api.anthropic.com/v1/messages',
      {
        model: 'claude-3-haiku-20240307',
        max_tokens: 10,
        messages: [{ role: 'user', content: 'Hello' }]
      },
      {
        headers: {
          'x-api-key': process.env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        timeout: 5000
      }
    );

    if (response.status === 200 && response.data.content) {
      console.log(`   ✓ Anthropic API key valid`);
      console.log(`   Response received: ${response.data.content[0].text.substring(0, 20)}...`);
      return true;
    } else {
      console.log(`   ✗ Anthropic API key invalid: Unexpected response`);
      return false;
    }
