    if (error.response) {
      console.log(`   ✗ Anthropic API key invalid: ${error.response.status} - ${error.response.data.error?.message || error.response.data}`);
    } else {
      console.log(`   ✗ Anthropic API key invalid: ${error.message}`);
    }
    return false;
  }
}

