async function testLogfireToken() {
  console.log('\n5. Testing Logfire Token...');
  console.log(`   ⚠ Logfire token verification skipped - no public validation endpoint available`);
  console.log(`   Token format appears valid: ${process.env.LOGFIRE_TOKEN.substring(0, 10)}...`);
  return true; // Assume valid for now since we can't test
}

