async function runTests() {
  console.log('='.repeat(60));
  console.log('CREDENTIAL VALIDATION TEST');
  console.log('='.repeat(60));

  // Check if required packages are installed, install if missing
  const requiredPackages = ['pg', 'axios', '@aws-sdk/client-sts'];
  const missingPackages = [];

  for (const pkg of requiredPackages) {
    try {
      require.resolve(pkg);
    } catch (e) {
      missingPackages.push(pkg);
    }
  }

  if (missingPackages.length > 0) {
    console.log(`Missing required packages: ${missingPackages.join(', ')}`);
    console.log('Installing missing packages...');
    const { execSync } = require('child_process');
    try {
      execSync(`npm install ${missingPackages.join(' ')}`, { stdio: 'inherit' });
    } catch (installError) {
      console.log(`Failed to install packages: ${installError.message}`);
      return;
    }
  }

  // Run tests
  const results = [];
  results.push(await testDatabaseConnection());
  results.push(await testAWSCredentials());
  results.push(await testAnthropicAPIKey());
  results.push(await testStripeSecretKey());
  results.push(await testLogfireToken());

  // Summary
  console.log('\n' + '='.repeat(60));
  console.log('TEST SUMMARY');
  console.log('='.repeat(60));

  const testNames = [
    'Database Connection',
    'AWS Credentials',
    'Anthropic API Key',
    'Stripe Secret Key',
    'Logfire Token'
  ];

  let passed = 0;
  results.forEach((result, index) => {
    const status = result ? 'PASS' : 'FAIL';
    console.log(`${testNames[index]}: ${status}`);
    if (result) passed++;
  });

  console.log(`\nTotal: ${passed}/${results.length} tests passed`);

  if (passed === results.length) {
    console.log('🎉 All credentials appear to be valid!');
  } else {
    console.log('⚠️  Some credentials may be invalid or expired');
  }
}

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.log('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Run the tests
runTests().catch(console.error);

