// Verification script for credentials in .env.test
require('dotenv').config({ path: './.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');
  try {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    const res = await client.query('SELECT version()');
    await client.end();
    console.log('✓ Database connection successful');
    console.log(`  PostgreSQL version: ${res.rows[0].version}`);
    return true;
  } catch (error) {
    console.log('✗ Database connection failed:');
    console.log(`  ${error.message}`);
    return false;
  }
}

async function testAWSCredentials() {
  console.log('\nTesting AWS credentials...');
  try {
    // Configure AWS with credentials from env
    AWS.config.update({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1' // Default region
    });

    // Try to call a simple AWS API (STS GetCallerIdentity)
    const sts = new AWS.STS();
    const data = await sts.getCallerIdentity().promise();
    console.log('✓ AWS credentials valid');
    console.log(`  Account ID: ${data.Account}`);
    console.log(`  User ID: ${data.UserId}`);
    return true;
  } catch (error) {
    console.log('✗ AWS credentials validation failed:');
    console.log(`  ${error.message}`);
    return false;
  }
}

async function testAnthropicAPI() {
  console.log('\nTesting Anthropic API key...');
  try {
    if (!process.env.ANTHROPIC_API_KEY) {
      console.log('✗ Anthropic API key not found');
      return false;
    }

    const response = await axios.post(
      'https://api.anthropic.com/v1/messages',
      {
        model: 'claude-3-haiku-20240307',
        max_tokens: 10,
        messages: [{ role: 'user', content: 'Hello' }]
      },
      {
        headers: {
          'x-api-key': process.env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        }
      }
    );

    console.log('✓ Anthropic API key valid');
    console.log(`  Response ID: ${response.data.id}`);
    return true;
  } catch (error) {
    console.log('✗ Anthropic API key validation failed:');
    if (error.response) {
      console.log(`  Status: ${error.response.status}`);
      console.log(`  Message: ${error.response.data.error?.message || error.response.data}`);
    } else {
      console.log(`  ${error.message}`);
    }
    return false;
  }
}

async function testStripeAPI() {
  console.log('\nTesting Stripe API key...');
  try {
    if (!process.env.STRIPE_SECRET_KEY) {
      console.log('✗ Stripe API key not found');
      return false;
    }

    const response = await axios.get(
      'https://api.stripe.com/v1/account',
      {
        headers: {
          'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`
        }
      }
    );

    console.log('✓ Stripe API key valid');
    console.log(`  Account ID: ${response.data.id}`);
    return true;
  } catch (error) {
    console.log('✗ Stripe API key validation failed:');
    if (error.response) {
      console.log(`  Status: ${error.response.status}`);
      console.log(`  Message: ${error.response.data.error?.message || error.response.data}`);
    } else {
      console.log(`  ${error.message}`);
    }
    return false;
  }
}

async function testLogfireToken() {
  console.log('\nTesting Logfire token...');
  try {
    if (!process.env.LOGFIRE_TOKEN) {
      console.log('✗ Logfire token not found');
      return false;
    }

    // Logfire uses HTTP endpoint for token validation
    const response = await axios.post(
      'https://logfire-api.pydantic.dev/v1/validate',
      { token: process.env.LOGFIRE_TOKEN },
      {
        headers: {
          'Content-Type': 'application/json'
        }
      }
    );

    console.log('✓ Logfire token valid');
    console.log(`  Status: ${response.data.status}`);
    return true;
  } catch (error) {
    console.log('✗ Logfire token validation failed:');
    if (error.response) {
      console.log(`  Status: ${error.response.status}`);
      console.log(`  Message: ${error.response.data.message || error.response.data}`);
    } else {
      console.log(`  ${error.message}`);
    }
    return false;
  }
}

async function runAllTests() {
  console.log('Starting credential verification...\n');

  const results = await Promise.allSettled([
    testDatabaseConnection(),
    testAWSCredentials(),
    testAnthropicAPI(),
    testStripeAPI(),
    testLogfireToken()
  ]);

  const [dbResult, awsResult, anthropicResult, stripeResult, logfireResult] = results;

  console.log('\n' + '='.repeat(50));
  console.log('SUMMARY:");
  console.log('='.repeat(50));
  console.log(`Database Connection: ${dbResult.status === 'fulfilled' && dbResult.value ? 'PASS' : 'FAIL'}`);
  console.log(`AWS Credentials:     ${awsResult.status === 'fulfilled' && awsResult.value ? 'PASS' : 'FAIL'}`);
  console.log(`Anthropic API:       ${anthropicResult.status === 'fulfilled' && anthropicResult.value ? 'PASS' : 'FAIL'}`);
  console.log(`Stripe API:          ${stripeResult.status === 'fulfilled' && stripeResult.value ? 'PASS' : 'FAIL'}`);
  console.log(`Logfire Token:       ${logfireResult.status === 'fulfilled' && logfireResult.value ? 'PASS' : 'FAIL'}`);

  const passed = results.filter(r => r.status === 'fulfilled' && r.value).length;
  console.log(`\nTotal: ${passed}/5 tests passed`);

  return passed === 5;
}

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.log('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Run tests if script is executed directly
if (require.main === module) {
  runAllTests()
