      console.error('Unexpected error during testing:', err);
      process.exit(1);
    });
}

module.exports = {
  testDatabaseConnection,
  testAWSCredentials,
  testAnthropicAPI,
  testStripeAPI,
  testLogfireToken,
  runAllTests
};

