    return false;
  }
}

function validateAWSKeys() {
  console.log('\nChecking AWS credentials format...');

  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKey || !secretKey) {
    console.log('✗ AWS credentials not fully defined');
    return false;
  }

  // AWS Access Key ID format: 20 characters, uppercase alphanumeric
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  if (!accessKeyPattern.test(accessKey)) {
    console.log('✗ AWS_ACCESS_KEY_ID format appears invalid');
    console.log('  Expected format: AKIA followed by 16 uppercase alphanumeric characters');
    return false;
  }

  // AWS Secret Access Key format: 40 characters, alphanumeric and punctuation
  const secretKeyPattern = /^[0-9a-zA-Z\/+]{40}$/;
  if (!secretKeyPattern.test(secretKey)) {
    console.log('✗ AWS_SECRET_ACCESS_KEY format appears invalid');
    console.log('  Expected format: 40 character alphanumeric string');
    return false;
  }

  console.log('✓ AWS credentials format appears valid');
  console.log(`  Access Key ID: ${accessKey.substring(0, 4)}...${accessKey.slice(-4)}`);
  console.log(`  Secret Key: ${secretKey.substring(0, 4)}...${secretKey.slice(-4)}`);
  return true;
}

function validateAPIKey(formatName, key, pattern, example) {
  console.log(`\nChecking ${formatName} format...`);

  if (!key) {
    console.log(`✗ ${formatName} not defined`);
    return false;
  }

  if (!pattern.test(key)) {
    console.log(`✗ ${formatName} format appears invalid`);
    console.log(`  Expected format: ${example}`);
    return false;
  }

  console.log(`✓ ${formatName} format appears valid`);
  console.log(`  Key: ${key.substring(0, 8)}...${key.slice(-8)}`);
  return true;
}

function main() {
  const results = [];

  // Check DATABASE_URL
  results.push(validateDatabaseURL(process.env.DATABASE_URL));

  // Check AWS credentials
  results.push(validateAWSKeys());

  // Check Anthropic API key (sk-ant- followed by alphanumeric and hyphens)
  results.push(validateAPIKey(
    'Anthropic API key',
    process.env.ANTHROPIC_API_KEY,
    /^sk-ant-[0-9a-zA-Z\-]+$/,
    'sk-ant- followed by alphanumeric characters and hyphens'
  ));

  // Check Stripe secret key (sk_live_ or sk_test_ followed by alphanumeric)
  results.push(validateAPIKey(
    'Stripe secret key',
    process.env.STRIPE_SECRET_KEY,
    /^sk_(live|test)_[0-9a-zA-Z]+$/,
    'sk_live_ or sk_test_ followed by alphanumeric characters'
  ));

  // Check Logfire token (basic format check)
  results.push(validateAPIKey(
    'Logfire token',
    process.env.LOGFIRE_TOKEN,
    /^[0-9a-zA-Z\-]+$/, // Simple alphanumeric and hyphens
    'alphanumeric characters and hyphens'
  ));

  console.log('\n' + '='.repeat(50));
  console.log('FORMAT VALIDATION SUMMARY:');
  console.log('='.repeat(50));

  const labels = [
    'DATABASE_URL',
    'AWS Credentials', 
    'Anthropic API Key',
    'Stripe Secret Key',
    'Logfire Token'
  ];

  labels.forEach((label, index) => {
    console.log(`${label.padEnd(25)}: ${results[index] ? 'PASS' : 'FAIL'}`);
  });

  const passed = results.filter(Boolean).length;
  console.log(`\nFormat Validation: ${passed}/${results.length} checks passed`);

  // Additional note about actual validation
  console.log('\nNOTE: This script only validates format, not actual validity.');
  console.log('To truly verify these credentials, you would need to:');
  console.log('1. Install required packages (pg, aws-sdk, axios)');
  console.log('2. Make actual API calls to each service');
  console.log('3. Handle network connectivity and service availability');

  return passed === results.length;
}

// Run if executed directly
if (require.main === module) {
  const success = main();
  process.exit(success ? 0 : 1);
}

module.exports = {
  validateDatabaseURL,
  validateAWSKeys,
  validateAPIKey,
  main
};

