function testURLConnectivity(testName, testUrl, options = {}) {
  return new Promise((resolve) => {
    console.log(`Testing ${testName}...`);

    const parsedUrl = new URL(testUrl);
    const requestOptions = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || 443,
      path: parsedUrl.pathname + parsedUrl.search,
      method: 'GET',
      headers: options.headers || {},
      timeout: 5000
    };

    // Add authorization header if provided
    if (options.token) {
      requestOptions.headers.Authorization = `Bearer ${options.token}`;
    }

    const req = https.request(requestOptions, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ ${testName} successful (HTTP ${res.statusCode})`);
          resolve(true);
        } else {
          console.log(`✗ ${testName} failed (HTTP ${res.statusCode}): ${data.substring(0, 100)}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`✗ ${testName} failed: ${error.message}`);
      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      console.log(`✗ ${testName} failed: Request timeout`);
      resolve(false);
    });

    req.end();
  });
}

