#!/usr/bin/env node
/**
 * Test script to validate credentials in .env.test
 * Checks connectivity to database and validates API key formats
 */

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const fetch = require('node-fetch');

// Load environment variables
const {
  DATABASE_URL,
  AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN
} = process.env;

console.log('Testing credentials from .env.test\n');

// Test Database Connection
async function testDatabase() {
  console.log('1. Testing Database Connection...');
  if (!DATABASE_URL) {
    console.log('   ❌ DATABASE_URL not found');
    return false;
  }

  try {
    const client = new Client({ connectionString: DATABASE_URL });
    await client.connect();
    const res = await client.query('SELECT version()');
    console.log(`   ✅ Database connected: ${res.rows[0].version.substring(0, 50)}...`);
    await client.end();
    return true;
  } catch (error) {
    console.log(`   ❌ Database connection failed: ${error.message}`);
    return false;
  }
}

// Test AWS Credentials Format
function testAWS() {
  console.log('\n2. Testing AWS Credentials Format...');
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    console.log('   ❌ AWS credentials not found');
    return false;
  }

  // AWS Access Key ID format: AKIA followed by 16 alphanumeric characters
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  // AWS Secret Access Key format: 40 character string
  const secretKeyPattern = /^[0-9a-zA-Z\/+]{40}$/;

  const accessKeyValid = accessKeyPattern.test(AWS_ACCESS_KEY_ID);
  const secretKeyValid = secretKeyPattern.test(AWS_SECRET_ACCESS_KEY);

  if (accessKeyValid && secretKeyValid) {
    console.log('   ✅ AWS credentials format appears valid');
    return true;
  } else {
    console.log(`   ❌ AWS credentials format invalid:`);
    console.log(`      Access Key ID valid: ${accessKeyValid} (pattern: AKIA[0-9A-Z]{16})`);
    console.log(`      Secret Access Key valid: ${secretKeyValid} (pattern: 40 char alphanumeric/+/_)`);
    return false;
  }
}

// Test Anthropic API Key Format
function testAnthropic() {
  console.log('\n3. Testing Anthropic API Key Format...');
  if (!ANTHROPIC_API_KEY) {
    console.log('   ❌ ANTHROPIC_API_KEY not found');
    return false;
  }

  // Anthropic API keys typically start with 'sk-ant-' followed by alphanumeric characters
  const anthropicPattern = /^sk-ant-[0-9a-zA-Z\-_]+$/;
  const isValid = anthropicPattern.test(ANTHROPIC_API_KEY);

  if (isValid) {
    console.log('   ✅ Anthropic API key format appears valid');
    return true;
  } else {
    console.log(`   ❌ Anthropic API key format invalid (expected pattern: sk-ant-[alphanumeric\-_]+)`);
    return false;
  }
}

// Test Stripe Secret Key Format
function testStripe() {
  console.log('\n4. Testing Stripe Secret Key Format...');
  if (!STRIPE_SECRET_KEY) {
    console.log('   ❌ STRIPE_SECRET_KEY not found');
    return false;
  }

  // Stripe secret keys start with 'sk_live_' or 'sk_test_' followed by alphanumeric characters
  const stripePattern = /^sk_(live|test)_ [0-9a-zA-Z]{24,}$/;
  const isValid = stripePattern.test(STRIPE_SECRET_KEY);

  if (isValid) {
    console.log('   ✅ Stripe secret key format appears valid');
    return true;
  } else {
    console.log(`   ❌ Stripe secret key format invalid (expected pattern: sk_(live|test)_[alphanumeric]{24,})`);
    return false;
  }
}

// Test Logfire Token Format (basic validation)
function testLogfire() {
  console.log('\n5. Testing Logfire Token Format...');
  if (!LOGFIRE_TOKEN) {
    console.log('   ❌ LOGFIRE_TOKEN not found');
    return false;
  }

  // Basic validation: token should be a reasonable length string
  const isValid = LOGFIRE_TOKEN.length >= 20 && LOGFIRE_TOKEN.includes('-');

  if (isValid) {
    console.log('   ✅ Logfire token format appears valid');
    return true;
  } else {
    console.log(`   ❌ Logfire token format appears invalid (too short or missing expected format)`);
    return false;
  }
}

// Perform actual API validation for services that support it
async def testActualAPIs() {
  console.log('\n6. Testing Actual API Responses (where possible)...');

  // Test Database with a simple query
  const dbResult = await testDatabase();

  // For security reasons, we won't actually make calls to external APIs with these keys
  // as they might be valid and we don't want to incur charges or trigger abuse prevention
  console.log('   ⚠️  Skipping actual API calls to avoid potential charges or abuse triggers');
  console.log('   ℹ️  In a real test environment, you would:');
  console.log('      - Use test/sandbox modes for payment APIs');
  console.log('      - Use development/staging endpoints');
  console.log('      - Implement rate limiting and error handling');

  return dbResult; // Only return database test result for now
}

// Main execution
async function main() {
  console.log('Starting credential validation tests...\n');

  const results = {
    database: await testDatabase(),
    aws: testAWS(),
    anthropic: testAnthropic(),
    stripe: testStripe(),
    logfire: testLogfire()
  };

  // Summary
  console.log('\n' + '='.repeat(50));
  console.log('TEST SUMMARY:');
  console.log('='.repeat(50));

  let passed = 0;
  const total = Object.keys(results).length;

  for (const [test, result] of Object.entries(results)) {
    const status = result ? '✅ PASS' : '❌ FAIL';
    console.log(`${test.padEnd(15)}: ${status}`);
    if (result) passed++;
  }

  console.log(`\nTOTAL: ${passed}/${total} tests passed`);

  if (passed === total) {
    console.log('🎉 All credential format tests passed!');
    return 0;
  } else {
    console.log('⚠️  Some tests failed - review output above');
    return 1;
  }
}

// Run tests if script is executed directly
if (require.main === module) {
  main().then(process.exit).catch(err => {
    console.error('Unhandled error in test script:', err);
    process.exit(1);
  });
}

module.exports = { testDatabase, testAWS, testAnthropic, testStripe, testLogfire };

