#!/usr/bin/env node
/**
 * Simple test script to validate credentials in .env.test
 * Checks format validity without external dependencies
 */

// Load .env.test file manually
const fs = require('fs');
const path = require('path');

function loadEnvFile(filePath) {
  const envVars = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
      line = line.trim();
      // Skip empty lines and comments
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          const value = valueParts.join('=');
          envVars[key.trim()] = value.trim();
        }
      }
    });
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
  }
  return envVars;
}

// Load environment variables from .env.test
const envVars = loadEnvFile(path.join(__dirname, '.env.test'));

console.log('Testing credentials from .env.test\n');

// Test Database URL format
function testDatabaseURL() {
  console.log('1. Testing Database URL...');
  const dbUrl = envVars.DATABASE_URL;

  if (!dbUrl) {
    console.log('   ❌ DATABASE_URL not found');
    return false;
  }

  // Basic PostgreSQL URL format validation
  const pgPattern = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/\S+$/;
  const isValid = pgPattern.test(dbUrl);

  if (isValid) {
    console.log('   ✅ DATABASE_URL format appears valid');
    // Try to extract host for additional info
    try {
      const url = new URL(dbUrl);
      console.log(`      Host: ${url.hostname}:${url.port || 5432}`);
      console.log(`      Database: ${url.pathname.substring(1)}`);
    } catch (e) {
      // Fallback if URL constructor fails
      console.log('      Unable to parse URL details');
    }
    return true;
  } else {
    console.log(`   ❌ DATABASE_URL format invalid`);
    console.log(`      Expected format: postgres://user:password@host:port/database`);
    return false;
  }
}

// Test AWS Credentials Format
