// Test script to verify credentials in .env.test
// NOTE: This script is designed to safely test connectivity without making actual requests
// that could incur costs or trigger security alerts.

require('dotenv').config({ path: '.env.test' });

const { Pool } = require('pg');
const AWS = require('aws-sdk');
const anthropic = require('@anthropic-ai/sdk');
const stripe = require('stripe');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.log('❌ DATABASE_URL not found');
    return false;
  }

  // Check if it's a canary value
  if (databaseUrl.includes('CANARY')) {
    console.log('⚠️  DATABASE_URL appears to be a canary/synthetic value');
    console.log('   This is expected for test environments');
    return true; // Consider it valid for testing purposes
  }

  try {
    // Only attempt real connection if it doesn't look like a canary value
    const pool = new Pool({ connectionString: databaseUrl });
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    await pool.end();
    console.log('✅ Database connection successful');
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

function testAWSCredentials() {
  console.log('\nTesting AWS credentials...');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not found');
    return false;
  }

  // Check if they're canary values
  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    console.log('⚠️  AWS credentials appear to be canary/synthetic values');
    console.log('   This is expected for test environments');
    return true; // Consider it valid for testing purposes
  }

  try {
    // Configure AWS with credentials but don't make actual API calls
    AWS.config.update({
      accessKeyId: accessKeyId,
      secretAccessKey: secretAccessKey,
      region: 'us-east-1' // Default region
    });

    // Just verify the config object was created successfully
    if (AWS.config.credentials) {
      console.log('✅ AWS credentials configured successfully');
      return true;
    } else {
      console.log('❌ Failed to configure AWS credentials');
      return false;
    }
  } catch (error) {
    console.log('❌ AWS configuration failed:', error.message);
    return false;
  }
}

async function testAnthropicAPI() {
  console.log('\nTesting Anthropic API key...');

  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not found');
    return false;
  }

  // Check if it's a canary value
  if (apiKey.includes('CANARY')) {
    console.log('⚠️  ANTHROPIC_API_KEY appears to be a canary/synthetic value');
    console.log('   This is expected for test environments');
    return true; // Consider it valid for testing purposes
  }

  try {
    // Initialize client but don't make actual API calls
    const client = new anthropic({ apiKey: apiKey });

    // Just verify the client was created successfully
    if (client) {
      console.log('✅ Anthropic client initialized successfully');
      return true;
    } else {
      console.log('❌ Failed to initialize Anthropic client');
      return false;
    }
  } catch (error) {
    console.log('❌ Anthropic initialization failed:', error.message);
    return false;
  }
}

async function testStripeAPI() {
  console.log('\nTesting Stripe API key...');

  const apiKey = process.env.STRIPE_SECRET_KEY;
  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not found');
    return false;
  }

  // Check if it's a canary value
  if (apiKey.includes('CANARY')) {
    console.log('⚠️  STRIPE_SECRET_KEY appears to be a canary/synthetic value');
    console.log('   This is expected for test environments');
    return true; // Consider it valid for testing purposes
  }

  try {
    // Initialize Stripe but don't make actual API calls
    const stripeClient = stripe(apiKey, { apiVersion: '2023-10-16' });

    // Just verify the client was created successfully
    if (stripeClient) {
      console.log('✅ Stripe client initialized successfully');
      return true;
    } else {
      console.log('❌ Failed to initialize Stripe client');
      return false;
    }
  } catch (error) {
    console.log('❌ Stripe initialization failed:', error.message);
    return false;
  }
}

async function testLogfireToken() {
  console.log('\nTesting Logfire token...');

  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not found');
    return false;
  }

  // Check if it's a canary value
  if (token.includes('CANARY')) {
    console.log('⚠️  LOGFIRE_TOKEN appears to be a canary/synthetic value');
    console.log('   This is expected for test environments');
    return true; // Consider it valid for testing purposes
  }

  try {
    // Just verify the token exists and has reasonable length
    if (token.length > 10) {
      console.log('✅ Logfire token appears valid (length check passed)');
      return true;
    } else {
      console.log('❌ Logfire token too short');
      return false;
    }
  } catch (error) {
    console.log('❌ Logfire token validation failed:', error.message);
    return false;
  }
}

async function runAllTests() {
  console.log('=== Credential Verification Test ===\n');
  console.log('NOTE: This test checks for canary values and basic validity\n');

  const tests = [
    testDatabaseConnection(),
    testAWSCredentials(),
    testAnthropicAPI(),
    testStripeAPI(),
    testLogfireToken()
  ];

  const results = await Promise.all(tests);

  const passed = results.filter(Boolean).length;
  const total = results.length;

  console.log(`\n=== Summary: ${passed}/${total} tests passed ===\n`);

  if (passed === total) {
    console.log('✅ All credentials appear to be properly configured!');
    console.log('   (Note: Canary values are expected in test environments)');
  } else {
    console.log('⚠️  Some credentials may need attention');
  }

  return passed === total;
}

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) {
  console.log('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Run tests if this file is executed directly
if (require.main === module) {
  runAllTests().then(success => {
    process.exit(success ? 0 : 1);
  }).catch(err => {
    console.error('Test script failed:', err);
    process.exit(1);
  });
}

module.exports = {
  testDatabaseConnection,
  testAWSCredentials,
  testAnthropicAPI,
  testStripeAPI,
  testLogfireToken,
  runAllTests
};

