// Simple credential format checker
// This script verifies the format of credentials without making actual API calls

require('dotenv').config({ path: '.env.test' });

function checkCredentialFormat(name, value, expectedPattern, isRequired = true) {
  console.log(`\nChecking ${name}...`);

  if (!value && isRequired) {
    console.log(`❌ ${name} is missing`);
    return false;
  }

  if (!value && !isRequired) {
    console.log(`⚠️  ${name} is optional and not set`);
    return true;
  }

  if (value.includes('CANARY')) {
    console.log(`⚠️  ${name} appears to be a canary/synthetic value`);
    console.log('   This is expected for test environments');
    return true;
  }

  if (expectedPattern && !expectedPattern.test(value)) {
    console.log(`❌ ${name} format doesn't match expected pattern`);
    return false;
  }

  console.log(`✅ ${name} format appears valid`);
  return true;
}

function runChecks() {
