      process.env.DATABASE_URL, 
      /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/.+$/,
      true
    ),

    // AWS Access Key ID
    checkCredentialFormat(
      'AWS_ACCESS_KEY_ID', 
      process.env.AWS_ACCESS_KEY_ID, 
      /^AKIA[0-9A-Z]{16}$/,
      true
    ),

    // AWS Secret Access Key
    checkCredentialFormat(
      'AWS_SECRET_ACCESS_KEY', 
      process.env.AWS_SECRET_ACCESS_KEY, 
      /^[0-9a-zA-Z\/+]{40}$/, // Basic pattern for AWS secret keys
      true
    ),

    // Anthropic API Key
    checkCredentialFormat(
      'ANTHROPIC_API_KEY', 
      process.env.ANTHROPIC_API_KEY, 
      /^sk-ant-[0-9a-zA-Z\-]+$/,
      true
    ),

    // Stripe Secret Key
    checkCredentialFormat(
      'STRIPE_SECRET_KEY', 
      process.env.STRIPE_SECRET_KEY, 
      /^sk_(live|test)_[0-9a-zA-Z]+$/,
      true
    ),

    // Logfire Token
    checkCredentialFormat(
      'LOGFIRE_TOKEN', 
      process.env.LOGFIRE_TOKEN, 
      /.+/, // Any non-empty string
      true
    )
  ];

  const passed = checks.filter(Boolean).length;
  const total = checks.length;

  console.log(`\n=== Summary: ${passed}/${total} format checks passed ===\n`);

