// NOTE: These are marked as CANARY values, suggesting they are intentionally fake

require('dotenv').config({ path: '.env.test' });

const { Pool } = require('pg');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  try {
    const pool = new Pool({ connectionString: databaseUrl });
    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    await pool.end();
    console.log('✅ Database connection successful');
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

async function testAwsCredentials() {
  console.log('\nTesting AWS credentials...');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  // Check if they match the canary pattern
  if (accessKeyId.startsWith('REDACTED_AWS_AKID') || secretAccessKey.includes('CANARY')) {
    console.log('⚠️  AWS credentials appear to be canary/fake values');
    return false;
  }

  // In a real scenario, we would test with AWS SDK here
  // For safety with potentially fake credentials, we'll just validate format
  console.log('⚠️  Skipping live AWS test for safety with potentially fake credentials');
  return accessKeyId.length > 10 && secretAccessKey.length > 10;
}

async function testAnthropicApiKey() {
  console.log('\nTesting Anthropic API key...');

  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  // Check if it matches the canary pattern
