// Install required packages if not present
function checkAndInstallDependencies() {
  const fs = require('fs');
  const path = require('path');

  const packageJsonPath = path.resolve('./package.json');
  let packageJson = {};

  try {
    if (fs.existsSync(packageJsonPath)) {
      packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
    }
  } catch (err) {
    console.warn('Could not read package.json');
  }

  const dependencies = [...(packageJson.dependencies || []), ...(packageJson.devDependencies || [])];
  const hasPg = dependencies.includes('pg');
  const hasAxios = dependencies.includes('axios');
  const hasDotenv = dependencies.includes('dotenv');

  if (!hasPg || !hasAxios || !hasDotenv) {
    console.log('Installing required test dependencies...');
    const { execSync } = require('child_process');
    try {
      execSync('npm install pg axios dotenv --save-dev', { stdio: 'inherit' });
    } catch (error) {
      console.error('Failed to install dependencies:', error.message);
      process.exit(1);
    }
  }
}

