/**
 * Verification script for credentials found in .env.test
 * NOTE: This script makes actual network requests to verify credentials.
 * Use with caution as it may expose credentials in logs or network traces.
 */

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const axios = require('axios');

// Load environment variables
console.log('Loaded environment variables:');
console.log(`- DATABASE_URL: ${process.env.DATABASE_URL ? '[SET]' : '[NOT SET]'}`);
console.log(`- AWS_ACCESS_KEY_ID: ${process.env.AWS_ACCESS_KEY_ID ? '[SET]' : '[NOT SET]'}`);
console.log(`- AWS_SECRET_ACCESS_KEY: ${process.env.AWS_SECRET_ACCESS_KEY ? '[SET]' : '[NOT SET]'}`);
console.log(`- ANTHROPIC_API_KEY: ${process.env.ANTHROPIC_API_KEY ? '[SET]' : '[NOT SET]'}`);
console.log(`- STRIPE_SECRET_KEY: ${process.env.STRIPE_SECRET_KEY ? '[SET]' : '[NOT SET]'}`);
console.log(`- LOGFIRE_TOKEN: ${process.env.LOGFIRE_TOKEN ? '[SET]' : '[NOT SET]'}`);

async function testDatabaseConnection() {
  if (!process.env.DATABASE_URL) {
    console.log('\n❌ DATABASE_URL not set');
    return false;
  }

  try {
    console.log('\n🔍 Testing database connection...');
    const pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      // Timeout after 5 seconds
      connectionTimeoutMillis: 5000
    });

    // Try to connect and run a simple query
    const client = await pool.connect();
    try {
      const result = await client.query('SELECT version()');
      console.log('✅ Database connection successful');
      console.log(`   PostgreSQL version: ${result.rows[0].version.substring(0, 50)}...`);
      return true;
    } finally {
      client.release();
    }
  } catch (error) {
    console.log('❌ Database connection failed:');
    console.log(`   ${error.message}`);
    // Don't expose full error details that might contain sensitive info
    if (error.code) {
      console.log(`   Error code: ${error.code}`);
    }
    return false;
  }
}

async function testStripeKey() {
  if (!process.env.STRIPE_SECRET_KEY) {
    console.log('\n❌ STRIPE_SECRET_KEY not set');
    return false;
  }

  try {
    console.log('\n🔍 Testing Stripe API key...');
    // Using a safe endpoint that just validates the key
    const response = await axios.get('https://api.stripe.com/v1/account', {
      auth: {
        username: process.env.STRIPE_SECRET_KEY,
        password: '',
      },
      timeout: 5000
    });

    console.log('✅ Stripe API key is valid');
    return true;
  } catch (error) {
    console.log('❌ Stripe API key validation failed:');
    if (error.response) {
      console.log(`   Status: ${error.response.status}`);
      console.log(`   Message: ${error.response.data?.error?.message || 'Unknown error'}`);
    } else if (error.request) {
      console.log('   No response received (timeout or network issue)');
    } else {
      console.log(`   Error: ${error.message}`);
    }
    return false;
  }
}

async function testAnthropicKey() {
  if (!process.env.ANTHROPIC_API_KEY) {
    console.log('\n❌ ANTHROPIC_API_KEY not set');
    return false;
  }

  try {
    console.log('\n🔍 Testing Anthropic API key...');
    // Making a minimal request to validate the key
    const response = await axios.post('https://api.anthropic.com/v1/messages', {
      model: "claude-3-haiku-20240307",
      max_tokens: 1,
      messages: [{ role: "user", content: "hi" }]
    }, {
      headers: {
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      timeout: 5000
    });

    console.log('✅ Anthropic API key is valid');
    return true;
  } catch (error) {
    console.log('❌ Anthropic API key validation failed:');
    if (error.response) {
      console.log(`   Status: ${error.response.status}`);
      // Be careful not to leak the key in error messages
      const message = error.response.data?.error?.message || 'Unknown error';
      console.log(`   Message: ${message}`);
    } else if (error.request) {
      console.log('   No response received (timeout or network issue)');
    } else {
      console.log(`   Error: ${error.message}`);
    }
    return false;
  }
}

// Main execution
async function runVerification() {
  console.log('🔐 Starting credential verification...\n');

  const results = {
    database: await testDatabaseConnection(),
    stripe: await testStripeKey(),
    anthropic: await testAnthropicKey()
  };

  console.log('\n📊 Summary:');
  console.log(`   Database: ${results.database ? '✅ Valid' : '❌ Invalid/Unreachable'}`);
  console.log(`   Stripe:   ${results.stripe ? '✅ Valid' : '❌ Invalid'}`);
  console.log(`   Anthropic:${results.anthropic ? '✅ Valid' : '❌ Invalid'}`);

  const anyValid = Object.values(results).some(Boolean);
  if (!anyValid) {
    console.log('\n⚠️  WARNING: No credentials could be verified as valid');
    console.log('   This could mean:');
    console.log('   - Credentials are expired or revoked');
    console.log('   - Network restrictions prevent access');
    console.log('   - Services are unavailable');
    console.log('   - Credentials require different validation methods');
  } else {
    console.log('\n✅ At least some credentials appear to be valid');
  }

  return results;
}

// Run if executed directly
if (require.main === module) {
  runVerification().catch(console.error);
}

module.exports = { runVerification };

