  "dependencies": {
    "express": "^4.18.2",
    "express-rate-limit": "^6.7.0",
    "helmet": "^7.0.0",
    "xss-clean": "^0.1.1",
    "express-mongo-sanitize": "^2.2.0",
    "hpp": "^0.2.3"
  },
  "devDependencies": {
    "nodemon": "^3.0.1",
    "jest": "^29.5.0"
  },
  "engines": {
    "node": ">=14.0.0"
  }
}

/**
 * Test suite for the Express.js application
 * Demonstrates testing of error handling and validation
 */

const request = require('supertest');
const app = require('./app');

describe('Health Endpoint', () => {
  it('should return health status', async () => {
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
    expect(response.body.status).toBe('ok');
    expect(response.body).toHaveProperty('timestamp');
  });
});

describe('Users Endpoint', () => {
  it('should return users with default pagination', async () => {
    const response = await request(app).get('/users');
    expect(response.status).toBe(200);
    expect(response.body.status).toBe('success');
    expect(Array.isArray(response.body.data.users)).toBe(true);
    expect(response.body.data.users.length).toBeLessThanOrEqual(10);
  });

  it('should respect limit parameter', async () => {
    const response = await request(app).get('/users?limit=2');
    expect(response.status).toBe(200);
    expect(response.body.data.users.length).toBe(2);
  });

  it('should respect offset parameter', async () => {
    const response = await request(app).get('/users?offset=1&limit=2');
    expect(response.status).toBe(200);
    expect(response.body.data.users.length).toBe(2);
    // First user should be Bob (id: 2) since we skipped Alice (id: 1)
    expect(response.body.data.users[0].id).toBe(2);
  });

  it('should reject invalid limit values', async () => {
    // Test negative limit
    let response = await request(app).get('/users?limit=-1');
    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Validation failed');

    // Test zero limit
    response = await request(app).get('/users?limit=0');
    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Validation failed');

    // Test limit too high
    response = await request(app).get('/users?limit=101');
    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Validation failed');

    // Test non-numeric limit
    response = await request(app).get('/users?limit=abc');
    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Validation failed');
  });

  it('should reject invalid offset values', async () => {
    // Test negative offset
    let response = await request(app).get('/users?offset=-1');
    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Validation failed');

    // Test non-numeric offset
    response = await request(app).get('/users?offset=xyz');
    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Validation failed');
  });
});

describe('Error Handling', () => {
  it('should handle 404 for undefined routes', async () => {
    const response = await request(app).get('/undefined-route');
    expect(response.status).toBe(404);
    expect(response.body.status).toBe('error');
    expect(response.body.message).toContain('not found');
  });

  // Note: Testing 500 errors would require mocking internal failures
  // which is more complex and typically done with test doubles or 
  // by injecting test-specific error conditions
});

describe('Security Headers', () => {
  it('should include security headers', async () => {
    const response = await request(app).get('/health');
    // Helmet sets various security headers
    expect(response.headers).toHaveProperty('x-content-type-options');
    expect(response.headers).toHaveProperty('x-frame-options');
    // Note: Exact headers depend on helmet configuration
  });
});

afterAll(() => {
  // Close the server after tests
  return new Promise((resolve) => {
    // Assuming the app exports the server or we can access it
    setTimeout(resolve, 100); // Simple delay to allow cleanup
  });
});

