    const response = await fetch('https://api.stripe.com/v1/account', {
      headers: {
        'Authorization': `Bearer ${apiKey}`
      }
    });

    if (response.ok) {
      const data = await response.json();
      console.log('   ✅ Stripe secret key is valid');
      console.log(`   Account ID: ${data.id}`);
      return true;
    } else {
      const errorData = await response.text();
      console.log(`   ❌ Stripe API request failed: ${response.status} ${response.statusText}`);
      // Don't print full error as it might contain sensitive info
      return false;
    }
  } catch (apiErr) {
    console.log('   ❌ Stripe API request failed:', apiErr.message);
    return false;
  }
}

// 5. Test Logfire Token
async function testLogfireToken() {
  console.log('\n5. Testing Logfire Token...');
  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    console.log('   ❌ LOGFIRE_TOKEN not found in environment');
    return false;
  }

  // Check if this looks like a canary value
  if (token.includes('CANARY')) {
    console.log('   ⚠️  Logfire token appears to be a canary/test value');
    console.log('   ❌ Skipping actual API call to avoid potential security alerts');
    return false;
  }

  try {
    // Logfire typically uses tokens for authentication
