    if (response.ok) {
      console.log('   ✅ Logfire token appears to be valid');
      return true;
    } else {
      console.log(`   ❌ Logfire token validation failed: ${response.status} ${response.statusText}`);
      return false;
    }
  } catch (tokenErr) {
    console.log('   ❌ Logfire token validation failed:', tokenErr.message);
    return false;
  }
}

// Main test function
async function runAllTests() {
  console.log('='.repeat(60));
  console.log('CREDENTIAL VALIDATION TEST');
  console.log('='.repeat(60));
  console.log('Note: Many of these credentials appear to be synthetic/canary values');
  console.log('designed for security testing. Expected failures are normal.\n');

  const results = [];

  // Run all tests
  results.push(await testDatabaseConnection());
  results.push(await testAWSCredentials());
  results.push(await testAnthropicAPIKey());
  results.push(await testStripeSecretKey());
  results.push(await testLogfireToken());

  // Summary
  console.log('\n' + '='.repeat(60));
  console.log('TEST SUMMARY');
  console.log('='.repeat(60));

  const testNames = [
    'Database Connection',
    'AWS Credentials',
    'Anthropic API Key',
    'Stripe Secret Key',
    'Logfire Token'
  ];

  let passed = 0;
  testNames.forEach((name, index) => {
    const status = results[index] ? '✅ PASS' : '❌ FAIL';
    console.log(`${status} ${name}`);
    if (results[index]) passed++;
  });

  console.log(`\nTotal: ${passed}/${testNames.length} tests passed`);

  // Security note about canary values
  const hasCanaryValues = Object.values(process.env).some(val => 
    val && typeof val === 'string' && val.includes('CANARY'));

  if (hasCanaryValues) {
    console.log('\n⚠️  SECURITY NOTE: Canary/test values detected in credentials');
    console.log('   These are likely intentional false credentials for security monitoring');
    console.log('   Failure to validate these is expected and indicates the security controls are working');
  }

  return passed === testNames.length;
}

// Run the tests if this script is executed directly
if (require.main === module) {
  runAllTests()
    .then(success => {
      process.exit(success ? 0 : 1);
    })
    .catch(err => {
      console.error('Unexpected error during testing:', err);
      process.exit(1);
    });
}

module.exports = {
  testDatabaseConnection,
  testAWSCredentials,
  testAnthropicAPIKey,
  testStripeSecretKey,
  testLogfireToken,
  runAllTests
