/**
 * Simple credential validation script without external dependencies
 * Reads .env.test file directly and checks for obvious markers
 */

const fs = require('fs');
const path = require('path');

// Function to parse .env file manually
function parseEnvFile(filePath) {
  const envVars = {};

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
      // Skip empty lines and comments
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return;

      // Parse KEY=VALUE format
      const equalsIndex = trimmed.indexOf('=');
      if (equalsIndex > 0) {
        const key = trimmed.substring(0, equalsIndex).trim();
        let value = trimmed.substring(equalsIndex + 1).trim();

        // Remove quotes if present
        if (value.startsWith('"') && value.endsWith('"') && value.length >= 2) {
          value = value.substring(1, value.length - 1);
        } else if (value.startsWith("'") && value.endsWith("'") && value.length >= 2) {
          value = value.substring(1, value.length - 1);
        }

        envVars[key] = value;
      }
    });
  } catch (err) {
    console.error(`Error reading .env file: ${err.message}`);
    return null;
  }

  return envVars;
}

// Function to check if a value looks like a canary/test value
function isCanaryValue(value) {
  if (!value || typeof value !== 'string') return false;
  return value.includes('CANARY');
}

// Function to mask sensitive values for display
function maskValue(value, showChars = 4) {
  if (!value || typeof value !== 'string') return value;
  if (value.length <= showChars * 2) return '*'.repeat(value.length);
  return value.slice(0, showChars) + '*'.repeat(value.length - showChars * 2) + value.slice(-showChars);
}

// Main validation function
function validateCredentials() {
  console.log('='.repeat(60));
  console.log('CREDENTIAL FORMAT VALIDATION');
  console.log('='.repeat(60));
  console.log('Checking for obvious markers and format validity\n');

  // Load environment variables from .env.test
  const envVars = parseEnvFile(path.join(__dirname, '.env.test'));

  if (!envVars) {
    console.log('❌ Failed to load .env.test file');
    return false;
  }

  console.log(`Loaded ${Object.keys(envVars).length} environment variables from .env.test\n`);

  // 1. Validate DATABASE_URL
  console.log('1. DATABASE_URL Validation:');
  const databaseUrl = envVars.DATABASE_URL;
  if (databaseUrl) {
    console.log(`   Value: ${maskValue(databaseUrl)}`);

    if (isCanaryValue(databaseUrl)) {
      console.log('   ⚠️  Contains "CANARY" marker - likely a test/canary value');
    } else {
      console.log('   ℹ️  No obvious canary markers detected');
    }

    // Basic format check for PostgreSQL URL
    const pgUrlPattern = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/[^]+$/;
    if (pgUrlPattern.test(databaseUrl)) {
      console.log('   ✅ Format appears to be a valid PostgreSQL connection string');
    } else {
      console.log('   ❌ Format does not match expected PostgreSQL connection string pattern');
    }
  } else {
    console.log('   ❌ DATABASE_URL not found in environment');
  }
  console.log();

  // 2. Validate AWS Credentials
  console.log('2. AWS Credentials Validation:');
  const awsAccessKeyId = envVars.AWS_ACCESS_KEY_ID;
  const awsSecretAccessKey = envVars.AWS_SECRET_ACCESS_KEY;

  if (awsAccessKeyId) {
