// Improved application with better error handling and security practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Sanitize against XSS attacks
app.use(mongoSanitize()); // Sanitize against NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Health check endpoint with proper error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with input validation (placeholder for future expansion)
app.get('/users', (req, res) => {
  try {
    // In a real application, you might have query parameters here
    // that would need validation, such as:
    // const { limit, offset } = req.query;
    // Validate limit and offset here

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Unable to retrieve users' 
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found'
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Error:', error); // Log error for debugging

  // Determine status code
  const statusCode = error.statusCode || 500;

  // Don't leak stack trace in production
  const response = {
    status: 'error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : error.message
  };

  // Only include stack trace in development
  if (process.env.NODE_ENV !== 'production') {
    response.stack = error.stack;
  }

  res.status(statusCode).json(response);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

