/**
 * Test script to validate credentials from .env.test
 * NOTE: These are expected to be canary/test values and should fail validation
 */

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

async function testDatabaseConnection() {
  console.log('Testing database connection...');

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  try {
    // Extract connection details from URL
    const pool = new Pool({ connectionString: databaseUrl });

    // Try to connect with a timeout
    const client = await pool.connect();
    console.log('✅ Database connection successful');
    client.release();
    await pool.end();
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    return false;
  }
}

async function testAwsCredentials() {
  console.log('\nTesting AWS credentials...');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  // Check if these are canary values
  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    console.log('⚠️  AWS credentials appear to be canary/test values');
    return false;
  }

  try {
    // Configure AWS SDK
    AWS.config.update({
      accessKeyId,
      secretAccessKey,
      region: 'us-east-1' // Default region
    });

    // Try a simple operation (list S3 buckets)
    const s3 = new AWS.S3();
    const data = await s3.listBuckets().promise();
    console.log('✅ AWS credentials are valid');
    return true;
  } catch (error) {
    console.log(`❌ AWS validation failed: ${error.message}`);
    return false;
  }
}

async function testAnthropicApiKey() {
  console.log('\nTesting Anthropic API key...');

  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  // Check if this is a canary value
  if (apiKey.includes('CANARY')) {
    console.log('⚠️  Anthropic API key appears to be a canary/test value');
    return false;
  }

  try {
    // Test with a minimal request to Anthropic's API
    const response = await axios.post(
      'https://api.anthropic.com/v1/messages',
      {
        model: 'claude-instant-1',
        max_tokens: 1,
        messages: [{ role: 'user', content: 'Hello' }]
      },
      {
        headers: {
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        timeout: 5000
      }
    );

    console.log('✅ Anthropic API key is valid');
    return true;
  } catch (error) {
    console.log(`❌ Anthropic API validation failed: ${error.response?.data?.error?.message || error.message}`);
    return false;
  }
}

async function testStripeApiKey() {
  console.log('\nTesting Stripe API key...');

  const apiKey = process.env.STRIPE_SECRET_KEY;

  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not found in environment');
    return false;
  }

  // Check if this is a canary value
  if (apiKey.includes('CANARY')) {
    console.log('⚠️  Stripe API key appears to be a canary/test value');
    return false;
  }

  try {
    // Test with a minimal request to Stripe's API
    const response = await axios.get(
      'https://api.stripe.com/v1/account',
      {
        auth: {
          username: apiKey,
          password: '' // Stripe uses API key as username, empty password
        },
        timeout: 5000
      }
    );

    console.log('✅ Stripe API key is valid');
    return true;
  } catch (error) {
    console.log(`❌ Stripe API validation failed: ${error.response?.data?.error?.message || error.message}`);
    return false;
  }
}

async function testLogfireToken() {
  console.log('\nTesting Logfire token...');

  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not found in environment');
    return false;
  }

  // Check if this is a canary value
  if (token.includes('CANARY')) {
    console.log('⚠️  Logfire token appears to be a canary/test value');
    return false;
  }

  try {
    // Logfire doesn't have a simple public API to test tokens against
    // We'll just verify the token isn't empty and doesn't contain obvious test markers
    if (token.length > 10) {
      console.log('✅ Logfire token appears to be properly formatted');
      return true;
    } else {
      console.log('❌ Logfire token is too short');
      return false;
    }
  } catch (error) {
    console.log(`❌ Logfire token validation failed: ${error.message}`);
    return false;
  }
}

async function runAllTests() {
  console.log('=== Testing Credentials from .env.test ===\n');

  const tests = [
    testDatabaseConnection(),
    testAwsCredentials(),
    testAnthropicApiKey(),
    testStripeApiKey(),
    testLogfireToken()
  ];

  const results = await Promise.all(tests);

  console.log('\n=== Summary ===');
  const passed = results.filter(Boolean).length;
  const total = results.length;

  console.log(`Passed: ${passed}/${total}`);

  if (passed === 0) {
    console.log('ℹ️  All tests failed as expected - these appear to be canary/test values');
  } else if (passed < total) {
    console.log('⚠️  Some tests passed - verify if any real credentials were accidentally committed');
  } else {
    console.log('⚠️  All tests passed - verify these are intended to be valid credentials');
  }
}

// Check if required packages are installed, otherwise install them
const { execSync } = require('child_process');
const fs = require('fs');

function checkAndInstallDeps() {
  const packageJson = {
    dependencies: {
      'dotenv': '^16.0.0',
      'pg': '^8.0.0',
      'aws-sdk': '^2.0.0',
      'axios': '^1.0.0'
    }
  };

  // Write a temporary package.json for dependency installation
  fs.writeFileSync('./test-package.json', JSON.stringify(packageJson, null, 2));

  try {
    // Check if node_modules exists, if not install dependencies
    if (!fs.existsSync('./node_modules')) {
      console.log('Installing test dependencies...');
      execSync('npm install dotenv pg aws-sdk axios', { stdio: 'inherit' });
    }

    // Clean up
    fs.unlinkSync('./test-package.json');
  } catch (error) {
    console.error('Error installing dependencies:', error.message);
    process.exit(1);
  }
}

// Run the tests
checkAndInstallDeps().then(() => runAllTests().catch(console.error));

