// Simple credential format validation script
// Checks if credentials have the expected format without making network calls

const fs = require('fs');
const path = require('');

// Load .env.test file manually since we can't install dotenv
function loadEnvFile(filePath) {
  const env = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    lines.forEach(line => {
      line = line.trim();
      // Skip empty lines and comments
      if (!line || line.startsWith('#')) return;

      // Parse KEY=VALUE format
      const equalsIndex = line.indexOf('=');
      if (equalsIndex > 0) {
        const key = line.substring(0, equalsIndex).trim();
        const value = line.substring(equalsIndex + 1).trim();
        // Remove quotes if present
        env[key] = value.replace(/^['"]|['"]$/g, '');
      }
    });

    return env;
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
    return {};
  }
}

// Load environment variables from .env.test
const env = loadEnvFile('./.env.test');

// Function to mask sensitive data for logging
function maskCredentials(obj) {
  const masked = { ...obj };
  const sensitiveKeys = [
    'DATABASE_URL', 
    'AWS_SECRET_ACCESS_KEY', 
    'ANTHROPIC_API_KEY', 
    'STRIPE_SECRET_KEY', 
    'LOGFIRE_TOKEN'
  ];

  sensitiveKeys.forEach(key => {
    if (masked[key]) {
      // Show first and last 4 characters only
      const value = masked[key];
      if (value.length > 8) {
        masked[key] = value.substring(0, 4) + '****' + value.substring(value.length - 4);
      } else {
        masked[key] = '****';
      }
    }
  });

  return masked;
}

// Validation functions (format-only checks)
function validateDatabaseURL(url) {
  if (!url) return { valid: false, message: 'DATABASE_URL is missing' };

  // Basic PostgreSQL URL format check
  const pgUrlPattern = /^postgres:\/\/[^:]+:[^@]+@[^:]+:\d+\/.+$/;
  if (!pgUrlPattern.test(url)) {
    return { valid: false, message: 'DATABASE_URL does not match expected PostgreSQL format' };
  }

  return { valid: true, message: 'DATABASE_URL format appears valid' };
}

function validateAWSKeyPair(accessKeyId, secretAccessKey) {
  const issues = [];

  if (!accessKeyId) {
    issues.push('AWS_ACCESS_KEY_ID is missing');
  } else if (!/^AKIA[0-9A-Z]{16}$/.test(accessKeyId)) {
    issues.push('AWS_ACCESS_KEY_ID does not match expected format (AKIA followed by 16 alphanumeric characters)');
  }

  if (!secretAccessKey) {
    issues.push('AWS_SECRET_ACCESS_KEY is missing');
  } else if (secretAccessKey.length < 20) {
    issues.push('AWS_SECRET_ACCESS_KEY seems too short (should be 40 characters)');
  }

  if (issues.length === 0) {
    return { valid: true, message: 'AWS credentials format appears valid' };
  } else {
    return { valid: false, message: issues.join('; ') };
  }
}

function validateAPIKey(formatName, key, pattern, minLength = 10) {
  if (!key) {
    return { valid: false, message: `${formatName} is missing` };
  }

  if (key.length < minLength) {
    return { valid: false, message: `${formatName} seems too short (minimum ${minLength} characters)` };
  }

  if (pattern && !pattern.test(key)) {
    return { valid: false, message: `${formatName} does not match expected format` };
  }

  return { valid: true, message: `${formatName} format appears valid` };
}

function validateStripeSecretKey(key) {
  return validateAPIKey(
    'Stripe Secret Key', 
    key, 
    /^sk_(live|test)_[a-zA-Z0-9]+$/, 
    10
  );
}

function main() {
  console.log('=== Simple Credential Format Validation ===\n');
  console.log('Loaded environment variables:');
  console.log(JSON.stringify(maskCredentials(env), null, 2));
  console.log('\n');

  // Validate each credential type
  const results = {};

  // Database URL validation
  results.database = validateDatabaseURL(env.DATABASE_URL);
  console.log('=== Database URL Validation ===');
  console.log(`Status: ${results.database.valid ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Message: ${results.database.message}\n`);

  // AWS credentials validation
  results.aws = validateAWSKeyPair(env.AWS_ACCESS_KEY_ID, env.AWS_SECRET_ACCESS_KEY);
  console.log('=== AWS Credentials Validation ===');
  console.log(`Status: ${results.aws.valid ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Message: ${results.aws.message}\n`);

  // Anthropic API key validation
  results.anthropic = validateAPIKey(
    'Anthropic API Key', 
    env.ANTHROPIC_API_KEY, 
    /^sk-ant-[a-zA-Z0-9\-]+$/, 
    10
  );
  console.log('=== Anthropic API Key Validation ===');
  console.log(`Status: ${results.anthropic.valid ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Message: ${results.anthropic.message}\n`);

  // Stripe secret key validation
  results.stripe = validateStripeSecretKey(env.STRIPE_SECRET_KEY);
  console.log('=== Stripe Secret Key Validation ===');
  console.log(`Status: ${results.stripe.valid ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Message: ${results.stripe.message}\n`);

  // Logfire token validation (basic check)
  results.logfire = validateAPIKey(
    'Logfire Token', 
    env.LOGFIRE_TOKEN, 
    /^CANARY-[a-zA-Z0-9\-]+$/, 
    10
  );
  console.log('=== Logfire Token Validation ===');
  console.log(`Status: ${results.logfire.valid ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Message: ${results.logfire.message}\n`);

  // Summary
  console.log('=== VALIDATION SUMMARY ===');
  let allValid = true;
  Object.entries(results).forEach(([service, result]) => {
    const status = result.valid ? '✅ PASS' : '❌ FAIL';
    console.log(`${status} ${service.toUpperCase()}: ${result.message}`);
    if (!result.valid) allValid = false;
  });

  console.log(`\nOverall: ${allValid ? '✅ ALL CHECKS PASSED' : '❌ SOME CHECKS FAILED'}`);

  // Special note about CANARY values
  console.log('\n⚠️  IMPORTANT NOTE:');
  console.log('Several credentials contain "CANARY" in their values,');
  console.log('which indicates these are likely test/canary values.');
  console.log('Canary tokens are designed to detect unauthorized access or exfiltration.');
  console.log('If these are being used in production, they should be replaced with real credentials.');
}

main();

