// CREDENTIAL VALIDATION TEST SCRIPT
// ==================================
// This script attempts to validate the credentials found in .env.test
// IMPORTANT: Only run this in a secure, isolated environment
// Some credentials (like Stripe live keys) should NEVER be tested in production
// This is for educational/demo purposes only

require('dotenv').config({ path: '.env.test' });
const { Pool } = require('pg');
const axios = require('axios');

console.log('Starting credential validation test...');
console.log('====================================');

// Database connection test
async function testDatabaseConnection() {
  console.log('\n1. Testing Database Connection...');

  if (!process.env.DATABASE_URL) {
    console.log('   ❌ DATABASE_URL not found in environment');
    return false;
  }

  try {
    // Using ssl: false for local/test connections - adjust as needed
    const pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      ssl: process.env.DATABASE_URL.includes('localhost') || process.env.DATABASE_URL.includes('127.0.0.1') 
        ? false 
        : { rejectUnauthorized: false }
    });

    // Set a timeout for the connection attempt
    const timeoutPromise = new Promise((_, reject) => 
      setTimeout(() => reject(new Error('Connection timeout')), 5000)
    );

    const queryPromise = pool.query('SELECT NOW() as timestamp, version() as version');
    const result = await Promise.race([queryPromise, timeoutPromise]);

    console.log(`   ✅ Database connected successfully`);
    console.log(`   📅 Server time: ${result.rows[0].timestamp}`);
    console.log(`   🐘 PostgreSQL version: ${result.rows[0].version.substring(0, 50)}...`);

    await pool.end();
    return true;
  } catch (error) {
    console.log('   ❌ Database connection failed:');
    console.log(`      ${error.message}`);
    // Don't expose full error details that might contain sensitive info
    if (error.code) {
      console.log(`      Error code: ${error.code}`);
    }
    return false;
  }
}

// AWS credentials basic format validation
function testAWSCredentialsFormat() {
  console.log('\n2. Testing AWS Credentials Format...');

  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKey || !secretKey) {
    console.log('   ❌ AWS credentials not found');
    return false;
  }

  // AWS Access Key ID format: 20 characters, uppercase alphanumeric
  const accessKeyPattern = /^[A-Z0-9]{20}$/;
  // AWS Secret Access Key format: 40 characters, alphanumeric + punctuation
  const secretKeyPattern = /^[A-Za-z0-9\/+]{40}$/;

  const accessKeyValid = accessKeyPattern.test(accessKey);
  const secretKeyValid = secretKeyPattern.test(secretKey);

  if (accessKeyValid && secretKeyValid) {
    console.log('   ✅ AWS credentials format appears valid');
    console.log('   ⚠️  NOTE: This only validates format, not actual validity');
    return true;
  } else {
    console.log('   ❌ AWS credentials format invalid');
    if (!accessKeyValid) console.log('      Access Key ID format incorrect');
    if (!secretKeyValid) console.log('      Secret Access Key format incorrect');
    return false;
  }
}

// Anthropic API key format validation
function testAnthropicAPIKeyFormat() {
  console.log('\n3. Testing Anthropic API Key Format...');

  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('   ❌ ANTHROPIC_API_KEY not found');
    return false;
  }

  // Anthropic API keys typically start with 'sk-ant-' followed by alphanumeric characters
  const anthropicPattern = /^sk-ant-[A-Za-z0-9\-_]+$/;

  if (anthropicPattern.test(apiKey)) {
    console.log('   ✅ Anthropic API key format appears valid');
    console.log('   ⚠️  NOTE: This only validates format, not actual validity');
    return true;
  } else {
    console.log('   ❌ Anthropic API key format invalid');
    return false;
  }
}

// Stripe key format validation (WARNING: Testing live keys is dangerous!)
function testStripeKeyFormat() {
  console.log('\n4. Testing Stripe Key Format...');

  const secretKey = process.env.STRIPE_SECRET_KEY;

  if (!secretKey) {
    console.log('   ❌ STRIPE_SECRET_KEY not found');
    return false;
  }

  // Stripe secret keys typically start with 'sk_live_' or 'sk_test_'
  const stripePattern = /^sk_(live|test)_[A-Za-z0-9]+$/;

  if (stripePattern.test(secretKey)) {
    const keyType = secretKey.startsWith('sk_live_') ? 'LIVE' : 'TEST';
    console.log(`   ⚠️  Stripe key format valid (${keyType} key)`);

    if (keyType === 'LIVE') {
      console.log('   ❌ CRITICAL: Testing live Stripe keys is dangerous and against ToS!');
      console.log('   🛑 ABORTING: Do not validate live keys in this manner');
      return false; // Intentional fail for safety
    } else {
      console.log('   ✅ Test key format appears valid');
      console.log('   ⚠️  NOTE: This only validates format, not actual validity');
      return true;
    }
  } else {
    console.log('   ❌ Stripe key format invalid');
    return false;
  }
}

// Logfire token format validation
function testLogfireTokenFormat() {
  console.log('\n5. Testing Logfire Token Format...');

  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    console.log('   ❌ LOGFIRE_TOKEN not found');
    return false;
  }

  // Basic format check - tokens are usually alphanumeric with possible dashes/underscores
  if (token.length >= 10 && /^[A-Za-z0-9\-_]+$/.test(token)) {
    console.log('   ✅ Logfire token format appears valid');
    console.log('   ⚠️  NOTE: This only validates format, not actual validity');
    return true;
  } else {
    console.log('   ❌ Logfire token format invalid');
    return false;
  }
}

// Main execution function
async function main() {
  console.log('🔍 CREDENTIAL VALIDATION TEST');
  console.log('⚠️  WARNING: Only run in secure, isolated environments');
  console.log('⚠️  Never validate production credentials without authorization\n');

  // Load environment variables
  const dotenv = require('dotenv');
  const result = dotenv.config({ path: '.env.test' });

  if (result.error) {
    console.log('❌ Failed to load .env.test file');
    console.log(result.error);
    return;
  }

  console.log('✅ Loaded .env.test file');

  // Run tests
  const results = [];

  // Database test (actual connectivity)
  results.push(await testDatabaseConnection());

  // Format validation tests (safe)
  results.push(testAWSCredentialsFormat());
  results.push(testAnthropicAPIKeyFormat());
  results.push(testStripeKeyFormat()); // Will intentionally fail if live key
  results.push(testLogfireTokenFormat());

  // Summary
  console.log('\n' + '====================================');
  console.log('📊 TEST SUMMARY');
  console.log('====================================');

  const passed = results.filter(Boolean).length;
  const total = results.length;

  console.log(`✅ Passed: ${passed}/${total}`);
  console.log(`❌ Failed: ${total - passed}/${total}`);

  if (passed === total) {
    console.log('\n🎉 All format validations passed!');
    console.log('⚠️  Remember: Format validation ≠ actual credential validity');
  } else {
    console.log('\n⚠️  Some validations failed - review output above');
  }

  console.log('\n🔒 SECURITY REMINDER:');
  console.log('   - Never commit credential files to version control');
  console.log('   - Use secret management services in production');
  console.log('   - Rotate credentials regularly');
  console.log('   - Validate credentials only in authorized, secure environments');
}

// Run the test if script is executed directly
if (require.main === module) {
  main().catch(console.error);
}

module.exports = { 
  testDatabaseConnection,
  testAWSCredentialsFormat,
  testAnthropicAPIKeyFormat,
  testStripeKeyFormat,
  testLogfireTokenFormat
};

