// Validation functions
function validateAWS() {
  console.log('2. Checking AWS Credentials Format...');

  const accessKey = envVars.AWS_ACCESS_KEY_ID;
  const secretKey = envVars.AWS_SECRET_ACCESS_KEY;

  if (!accessKey || !secretKey) {
    console.log('   ❌ Missing AWS credentials');
    return false;
  }

  // AWS Access Key ID: 20 characters, uppercase alphanumeric
  const accessKeyPattern = /^[A-Z0-9]{20}$/;
  // AWS Secret Key: 40 characters, alphanumeric + / +
  const secretKeyPattern = /^[A-Za-z0-9\/+]{40}$/;

  const accessValid = accessKeyPattern.test(accessKey);
  const secretValid = secretKeyPattern.test(secretKey);

  if (accessValid && secretValid) {
    console.log('   ✅ AWS credentials format looks correct');
    return true;
  } else {
    console.log('   ❌ AWS credentials format issues:');
    if (!accessValid) console.log('      - Access Key ID should be 20 uppercase alphanumeric chars');
    if (!secretValid) console.log('      - Secret Key should be 40 alphanumeric + / + chars');
    return false;
  }
}

function validateAnthropic() {
  console.log('3. Checking Anthropic API Key Format...');

  const apiKey = envVars.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('   ❌ Missing ANTHROPIC_API_KEY');
    return false;
  }

  // Anthropic keys: sk-ant- followed by alphanumeric and hyphens/underscores
  const pattern = /^sk-ant-[A-Za-z0-9\-_]+$/;

  if (pattern.test(apiKey)) {
    console.log('   ✅ Anthropic API key format looks correct');
    return true;
  } else {
    console.log('   ❌ Anthropic API key format incorrect');
    console.log('      Expected format: sk-ant-[alphanumeric_hyphens_underscores]');
    return false;
  }
}

function validateStripe() {
  console.log('4. Checking Stripe Key Format...');

  const secretKey = envVars.STRIPE_SECRET_KEY;

  if (!secretKey) {
    console.log('   ❌ Missing STRIPE_SECRET_KEY');
    return false;
  }

  // Stripe keys: sk_live_ or sk_test_ followed by alphanumeric
  const pattern = /^sk_(live|test)_[A-Za-z0-9]+$/;

  if (!pattern.test(secretKey)) {
    console.log('   ❌ Stripe key format incorrect');
    console.log('      Expected format: sk_live_[alphanumeric] or sk_test_[alphanumeric]');
    return false;
  }

  const isLive = secretKey.startsWith('sk_live_');
  const keyType = isLive ? 'LIVE' : 'TEST';

  if (isLive) {
    console.log(`   🚨 LIVE STRIPE KEY DETECTED (${keyType})`);
    console.log('   ❌ CRITICAL SECURITY WARNING:');
    console.log('      - Testing live Stripe keys exposes you to financial risk');
    console.log('      - This violates Stripe\'s Terms of Service');
    console.log('      - Never validate live keys programmatically like this');
    console.log('      - IMMEDIATELY ROTATE THIS KEY IF IT WAS ACCIDENTALLY EXPOSED');
    return false; // Safety fail
  } else {
    console.log(`   ✅ Stripe ${keyType} key format looks correct`);
    return true;
  }
}

function validateLogfire() {
